{
  "name": "last-circle",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "Last Circle — a 3D tactical battle royale with looting, building, and a shrinking zone.",
  "scripts": {
    "dev": "vite --host 0.0.0.0",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^8.3.5"
  }
