:root {
  --ink: #080b0a;
  --ink-2: #0d1211;
  --panel: rgba(12, 17, 16, 0.74);
  --panel-solid: #111715;
  --cream: #f1ead9;
  --muted: #a5a99d;
  --dim: #72786e;
  --gold: #f2c14e;
  --gold-hot: #ffd66e;
  --orange: #e46b42;
  --red: #ef4f45;
  --blue: #60bce8;
  --green: #83d783;
  --line: rgba(241, 234, 217, 0.16);
  --line-soft: rgba(241, 234, 217, 0.08);
  --mono: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  --display: 'Barlow Condensed', 'Arial Narrow', Impact, sans-serif;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--cream);
  font-family: var(--display);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  position: fixed;
  inset: 0;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

button, input { font: inherit; }
button { color: inherit; }

.hidden { display: none !important; }

#stage { position: absolute; inset: 0; overflow: hidden; background: #9ab6c3; }
#game { display: block; width: 100%; height: 100%; outline: none; }

.stage-vignette {
  position: absolute; inset: 0; pointer-events: none;
  background:
    radial-gradient(130% 100% at 50% 38%, transparent 42%, rgba(3, 6, 5, 0.38) 100%),
    linear-gradient(180deg, rgba(5, 8, 7, 0.12), transparent 22%, transparent 74%, rgba(3, 6, 5, 0.45));
}

.stage-grain {
  position: absolute; inset: 0; pointer-events: none; opacity: 0.055; mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.88' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='160' height='160' filter='url(%23n)' opacity='0.65'/%3E%3C/svg%3E");
  background-size: 170px 170px;
}

#damage-vignette, #zone-vignette, #heal-vignette, #scope-overlay {
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
}

#damage-vignette {
  background: radial-gradient(circle at 50% 50%, transparent 28%, rgba(181, 27, 22, 0.7) 112%);
  transition: opacity 0.22s ease-out;
  z-index: 2;
}
#damage-vignette.hit { opacity: 1; transition: opacity 0.04s; }
#zone-vignette {
  background:
    radial-gradient(circle at 50% 50%, transparent 36%, rgba(37, 128, 173, 0.34) 100%),
    linear-gradient(180deg, rgba(64, 166, 209, 0.12), rgba(18, 66, 91, 0.2));
  z-index: 2;
  transition: opacity 0.4s;
}
#zone-vignette.active { opacity: 1; animation: zonePulse 2.2s ease-in-out infinite; }
#heal-vignette {
  background: radial-gradient(circle at 50% 60%, rgba(116, 209, 132, 0.12), transparent 60%);
  transition: opacity 0.5s;
  z-index: 2;
}
#heal-vignette.active { opacity: 1; }

#scope-overlay {
  z-index: 3;
  transition: opacity 0.16s;
  background: radial-gradient(circle at 50% 50%, transparent 0 29vh, rgba(0, 0, 0, 0.92) calc(29vh + 2px), #000 calc(29vh + 3px));
}
#scope-overlay.active { opacity: 1; }
#scope-overlay::before, #scope-overlay::after {
  content: ''; position: absolute; left: 50%; top: 50%; background: rgba(10, 15, 13, 0.8);
}
#scope-overlay::before { width: 1px; height: 58vh; transform: translate(-50%, -50%); }
#scope-overlay::after { height: 1px; width: 58vh; transform: translate(-50%, -50%); }

@keyframes zonePulse { 0%, 100% { opacity: 0.65; } 50% { opacity: 1; } }

/* ---------------- shared screen layers ---------------- */

.screen { position: absolute; inset: 0; z-index: 20; }

.eyebrow {
  display: inline-flex; align-items: center; gap: 10px;
  margin: 0; font-family: var(--mono); font-size: 10px; font-weight: 500;
  letter-spacing: 0.24em; text-transform: uppercase; color: var(--gold);
}
.eyebrow > span { width: 28px; height: 1px; background: var(--gold); display: inline-block; }

kbd {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 27px; height: 23px; padding: 0 6px;
  border: 1px solid rgba(241, 234, 217, 0.26);
  background: rgba(241, 234, 217, 0.06);
  border-radius: 2px; font-family: var(--mono); font-size: 9px;
  color: var(--cream); letter-spacing: 0.06em;
}

/* ---------------- boot ---------------- */

.boot {
  display: flex; align-items: center; justify-content: center; gap: 34px;
  background:
    radial-gradient(circle at 50% 42%, rgba(242, 193, 78, 0.08), transparent 38%),
    linear-gradient(160deg, #0a0e0d, #060808 70%);
  transition: opacity 0.7s ease, visibility 0.7s;
  z-index: 60;
}
.boot.done { opacity: 0; visibility: hidden; }
.boot-mark { color: var(--gold); animation: bootSpin 9s linear infinite; }
@keyframes bootSpin { to { transform: rotate(360deg); } }
.boot-copy h1 {
  margin: 8px 0 6px; font-size: clamp(48px, 7vw, 92px); line-height: 0.9;
  font-weight: 800; letter-spacing: 0.01em; color: var(--cream);
}
.boot-copy p { margin: 0 0 18px; font-family: var(--mono); font-size: 10px; letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; }
.boot-track { width: min(380px, 62vw); height: 2px; background: rgba(241, 234, 217, 0.12); overflow: hidden; }
.boot-track i { display: block; width: 100%; height: 100%; background: var(--gold); transform-origin: left; animation: bootLoad 1.4s cubic-bezier(0.2, 1, 0.2, 1) both; }
@keyframes bootLoad { from { transform: scaleX(0.08); } to { transform: scaleX(1); } }

/* ---------------- menu ---------------- */

.menu {
  display: flex; flex-direction: column;
  background:
    linear-gradient(100deg, rgba(5, 8, 7, 0.93) 0%, rgba(5, 8, 7, 0.74) 35%, rgba(5, 8, 7, 0.16) 67%, rgba(5, 8, 7, 0.34) 100%),
    linear-gradient(180deg, rgba(5, 8, 7, 0.48), transparent 24%, transparent 74%, rgba(5, 8, 7, 0.82));
  opacity: 1;
  transition: opacity 0.5s ease, visibility 0.5s;
}
.menu.leaving { opacity: 0; visibility: hidden; pointer-events: none; }
.menu-shade {
  position: absolute; inset: 0; pointer-events: none;
  background:
    repeating-linear-gradient(180deg, transparent 0 3px, rgba(3, 6, 5, 0.06) 3px 4px),
    linear-gradient(90deg, rgba(4, 7, 6, 0.46), transparent 32%);
  opacity: 0.45;
}

.menu-top {
  position: relative; z-index: 2; display: flex; justify-content: space-between; align-items: center;
  padding: calc(24px + var(--safe-t)) calc(38px + var(--safe-r)) 0 calc(38px + var(--safe-l));
}
.wordmark { display: flex; align-items: center; gap: 12px; }
.wordmark-sigil {
  display: grid; place-items: center; width: 42px; height: 42px;
  border: 1px solid rgba(242, 193, 78, 0.5); color: var(--gold);
  font-family: var(--display); font-weight: 800; font-size: 17px; letter-spacing: -0.04em;
  clip-path: polygon(0 0, 100% 0, 100% 72%, 72% 100%, 0 100%);
  background: rgba(242, 193, 78, 0.08);
}
.wordmark > span:last-child {
  display: flex; flex-direction: column; gap: 2px;
  font-size: 17px; font-weight: 700; line-height: 1; letter-spacing: 0.12em;
}
.wordmark em { font-family: var(--mono); font-style: normal; font-size: 7px; font-weight: 500; letter-spacing: 0.21em; color: var(--muted); }
.menu-meta { display: flex; align-items: center; gap: 22px; font-family: var(--mono); font-size: 9px; letter-spacing: 0.16em; color: var(--muted); }
.live-dot { display: inline-flex; align-items: center; gap: 7px; color: var(--green); }
.live-dot::before { content: ''; width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 10px var(--green); animation: liveBlink 2.4s infinite; }
@keyframes liveBlink { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }

.menu-body {
  position: relative; z-index: 2; flex: 1; display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(350px, 0.55fr);
  align-items: center; gap: 4vw;
