  text-shadow: 0 0 60px rgba(242, 193, 78, 0.16);
}
.tagline {
  max-width: 460px; margin: 0 0 30px; font-family: var(--mono); font-size: clamp(10px, 1vw, 12px);
  line-height: 1.8; letter-spacing: 0.04em; color: #c9c6b8; animation: rise 0.9s 0.32s both;
}
.tagline b { color: var(--cream); font-weight: 500; }
.hero-actions { display: flex; align-items: center; gap: 28px; animation: rise 0.9s 0.42s both; }
.deploy-btn {
  position: relative; display: flex; align-items: center; gap: 16px;
  min-width: 300px; height: 72px; padding: 0 24px 0 18px;
  border: 0; cursor: pointer; color: #15120a; text-align: left;
  background: linear-gradient(105deg, var(--gold-hot), var(--gold) 55%, #d9a52e);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px));
