  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.38), transparent);
  animation: deployShine 4.5s 1.4s infinite;
}
@keyframes deployShine { 0%, 55% { transform: translateX(-120%) skewX(-20deg); } 75%, 100% { transform: translateX(220%) skewX(-20deg); } }
.deploy-btn:hover { transform: translateY(-2px); filter: brightness(1.06); }
.deploy-btn:active { transform: translateY(0) scale(0.99); }
.deploy-glyph {
  display: grid; place-items: center; width: 42px; height: 42px;
  border: 1px solid rgba(21, 18, 10, 0.3); border-radius: 50%;
  font-size: 13px; padding-left: 3px;
}
.deploy-copy { display: flex; flex-direction: column; gap: 1px; }
.deploy-copy strong { font-size: 32px; line-height: 1; font-weight: 800; letter-spacing: 0.06em; }
.deploy-copy small { font-family: var(--mono); font-size: 8px; font-weight: 500; letter-spacing: 0.19em; }
.deploy-arrow { margin-left: auto; font-size: 24px; font-weight: 600; }
.match-facts { display: flex; flex-direction: column; gap: 6px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.17em; color: var(--muted); }
.match-facts span { display: flex; align-items: center; gap: 8px; }
.match-facts span::before { content: ''; width: 3px; height: 3px; background: var(--gold); border-radius: 50%; }

.feature-row {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); width: min(680px, 100%);
  margin-top: 38px; border-top: 1px solid var(--line); padding-top: 17px; gap: 15px;
  animation: rise 0.9s 0.52s both;
}
.feature-row div { display: flex; flex-direction: column; gap: 3px; }
.feature-row b { font-family: var(--mono); font-size: 8px; font-weight: 500; color: var(--gold); letter-spacing: 0.14em; }
.feature-row span { font-size: 20px; line-height: 1; font-weight: 700; letter-spacing: 0.1em; }
.feature-row small { font-family: var(--mono); font-size: 7px; letter-spacing: 0.08em; color: var(--dim); text-transform: uppercase; }

.briefing {
  position: relative; align-self: center; width: 100%; max-width: 430px; justify-self: end;
  padding: 24px 26px 20px; margin-bottom: 2vh;
  background: linear-gradient(155deg, rgba(15, 21, 19, 0.88), rgba(9, 13, 11, 0.76));
  border: 1px solid rgba(241, 234, 217, 0.14); border-top: 2px solid var(--gold);
  backdrop-filter: blur(14px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%);
  animation: slideIn 0.9s 0.5s both;
}
.briefing::before {
  content: ''; position: absolute; inset: 0; opacity: 0.5; pointer-events: none;
  background: repeating-linear-gradient(180deg, transparent 0 4px, rgba(255, 255, 255, 0.018) 4px 5px);
}
.briefing-head { display: flex; justify-content: space-between; align-items: baseline; border-bottom: 1px solid var(--line); padding-bottom: 13px; margin-bottom: 4px; }
.briefing-head span { font-size: 15px; font-weight: 700; letter-spacing: 0.17em; }
.briefing-head em { font-family: var(--mono); font-style: normal; font-size: 9px; color: var(--gold); letter-spacing: 0.14em; }
.briefing-step { display: flex; gap: 14px; padding: 13px 0; border-bottom: 1px solid var(--line-soft); }
.briefing-step > b { font-family: var(--mono); font-size: 9px; color: var(--gold); padding-top: 2px; font-weight: 500; }
.briefing-step strong { display: block; font-size: 14px; letter-spacing: 0.12em; font-weight: 600; }
.briefing-step p { margin: 4px 0 0; font-family: var(--mono); font-size: 8px; line-height: 1.7; letter-spacing: 0.02em; color: var(--muted); }
.controls-table { margin-top: 16px; display: flex; flex-direction: column; gap: 8px; }
.controls-table > div { display: grid; grid-template-columns: 46px 1fr 54px 1fr; align-items: center; gap: 7px; }
.controls-table span { font-family: var(--mono); font-size: 8px; letter-spacing: 0.1em; color: var(--muted); }
.controls-table kbd { min-width: 0; width: 100%; height: 22px; font-size: 8px; }
.briefing-foot {
  display: flex; align-items: center; gap: 8px; margin-top: 18px; padding-top: 13px; border-top: 1px solid var(--line);
  font-family: var(--mono); font-size: 7px; letter-spacing: 0.14em; color: var(--dim);
}
.briefing-foot em { margin-left: auto; font-style: normal; color: var(--muted); }
.signal { width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); }

.menu-footer {
  position: relative; z-index: 2; display: flex; align-items: center; justify-content: space-between;
  padding: 0 calc(38px + var(--safe-r)) calc(20px + var(--safe-b)) calc(38px + var(--safe-l));
  font-family: var(--mono); font-size: 8px; letter-spacing: 0.16em; color: var(--dim);
}
.menu-footer > span { display: flex; align-items: center; gap: 8px; }
.menu-footer i { width: 4px; height: 4px; border-radius: 50%; background: var(--gold); }
.sound-toggle {
  display: flex; align-items: center; gap: 8px; border: 1px solid var(--line); background: rgba(10, 14, 12, 0.5);
  padding: 7px 10px; cursor: pointer; font-family: var(--mono); font-size: 7px; letter-spacing: 0.14em; color: var(--muted);
  transition: border-color 0.2s, color 0.2s;
}
.sound-toggle b { color: var(--green); font-weight: 500; }
.sound-toggle.off b { color: var(--red); }
.sound-toggle:hover { border-color: rgba(242, 193, 78, 0.5); color: var(--cream); }

@keyframes rise { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }
@keyframes slideIn { from { opacity: 0; transform: translateX(26px); } to { opacity: 1; transform: translateX(0); } }

/* ---------------- HUD ---------------- */

#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }

.hud-top {
  position: absolute; top: 0; left: 0; right: 0;
  display: grid; grid-template-columns: minmax(180px, 1fr) minmax(280px, 500px) minmax(180px, 1fr);
  align-items: start; gap: 20px;
  padding: calc(17px + var(--safe-t)) calc(26px + var(--safe-r)) 0 calc(26px + var(--safe-l));
}
.brand { display: flex; align-items: center; gap: 11px; padding-top: 4px; }
.brand-mark {
