}
#compass { width: 100%; height: 100%; display: block; opacity: 0.94; }
.compass-pip { position: absolute; top: 0; left: 50%; width: 1px; height: 10px; background: var(--gold); transform: translateX(-50%); box-shadow: 0 0 8px rgba(242, 193, 78, 0.8); }
.compass-pip::after { content: ''; position: absolute; top: 10px; left: -3px; width: 5px; height: 5px; background: var(--gold); clip-path: polygon(0 0, 100% 0, 50% 100%); }

.match-stack { display: flex; justify-content: flex-end; align-items: flex-start; gap: 18px; }
.match-count { display: flex; flex-direction: column; align-items: flex-end; gap: 1px; padding-top: 3px; }
.match-count span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.2em; color: var(--muted); }
