}
.minimap-meta > span:first-child { font-size: 12px; letter-spacing: 0.14em; font-weight: 600; }
.minimap-meta .coord { font-family: var(--mono); font-size: 6px; letter-spacing: 0.04em; color: var(--dim); }

.killfeed {
  position: absolute; top: calc(79px + 234px + var(--safe-t)); right: calc(26px + var(--safe-r));
  width: 300px; display: flex; flex-direction: column; align-items: flex-end; gap: 5px;
}
.kill-entry {
  display: flex; align-items: center; gap: 7px; max-width: 100%;
  padding: 6px 9px; background: linear-gradient(90deg, rgba(8, 12, 10, 0.55), rgba(8, 12, 10, 0.88));
  border-right: 2px solid rgba(241, 234, 217, 0.3);
  font-family: var(--mono); font-size: 8px; letter-spacing: 0.05em; color: var(--muted);
  animation: feedIn 0.24s ease both;
}
.kill-entry.out { animation: feedOut 0.4s ease both; }
.kill-entry b { color: var(--cream); font-weight: 500; }
.kill-entry b.you { color: var(--gold); }
.kill-entry i { font-style: normal; color: var(--red); font-size: 9px; }
.kill-entry em { font-style: normal; color: var(--dim); font-size: 7px; text-transform: uppercase; }
@keyframes feedIn { from { opacity: 0; transform: translateX(18px); } }
@keyframes feedOut { to { opacity: 0; transform: translateX(18px); } }

.phase-banner {
  position: absolute; top: calc(84px + var(--safe-t)); left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  opacity: 0; transition: opacity 0.4s; text-align: center;
}
.phase-banner.visible { opacity: 1; }
.phase-banner span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.28em; color: var(--blue); }
