.drop-readout {
  position: absolute; top: 16%; left: 50%; transform: translateX(-50%);
  display: flex; align-items: baseline; gap: 7px; padding: 14px 20px;
  background: linear-gradient(180deg, rgba(8, 12, 10, 0.7), rgba(8, 12, 10, 0.34));
  border-top: 1px solid rgba(242, 193, 78, 0.6); backdrop-filter: blur(6px);
  text-align: center; flex-wrap: wrap; justify-content: center; min-width: 290px;
}
.drop-readout span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.18em; color: var(--muted); }
