.drop-readout em { font-family: var(--mono); font-style: normal; font-size: 10px; color: var(--gold); }
.drop-readout p { width: 100%; margin: 5px 0 0; font-family: var(--mono); font-size: 7px; letter-spacing: 0.08em; color: var(--dim); }

.crosshair { position: absolute; left: 50%; top: 50%; width: 0; height: 0; z-index: 5; --spread: 10px; }
.ch { position: absolute; background: rgba(245, 241, 230, 0.9); box-shadow: 0 0 3px rgba(0, 0, 0, 0.8); }
.ch-n { width: 1px; height: 7px; left: 0; top: calc(-1 * var(--spread) - 7px); }
.ch-s { width: 1px; height: 7px; left: 0; top: var(--spread); }
.ch-e { width: 7px; height: 1px; top: 0; left: var(--spread); }
.ch-w { width: 7px; height: 1px; top: 0; left: calc(-1 * var(--spread) - 7px); }
.ch-dot { position: absolute; width: 2px; height: 2px; left: -1px; top: -1px; background: var(--gold); box-shadow: 0 0 5px rgba(242, 193, 78, 0.9); }
.crosshair.aiming .ch { background: var(--gold); }
.hitmarker { position: absolute; left: 0; top: 0; width: 22px; height: 22px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; }
.hitmarker i { position: absolute; background: #fff; width: 1.5px; height: 7px; box-shadow: 0 0 3px rgba(0,0,0,.7); }
.hitmarker i:nth-child(1) { top: 0; left: 0; }
.hitmarker i:nth-child(2) { top: 0; right: 0; }
.hitmarker i:nth-child(3) { bottom: 0; left: 0; }
.hitmarker i:nth-child(4) { bottom: 0; right: 0; }
.hitmarker.show { animation: hitPop 0.24s ease both; }
.hitmarker.head i { background: var(--gold); }
.hitmarker.kill i { background: var(--red); height: 10px; }
@keyframes hitPop { 0% { opacity: 1; transform: translate(-50%, -50%) rotate(45deg) scale(0.55); } 60% { opacity: 1; } 100% { opacity: 0; transform: translate(-50%, -50%) rotate(45deg) scale(1.35); } }

.interact-prompt {
  position: absolute; left: 50%; bottom: 22%; transform: translateX(-50%);
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.1em; color: var(--gold);
  opacity: 0; transition: opacity 0.2s; text-align: center;
}
.interact-prompt.visible { opacity: 1; }

.vitals-panel {
  position: absolute; left: calc(26px + var(--safe-l)); bottom: calc(26px + var(--safe-b)); width: 300px;
  padding: 13px 15px 11px; background: linear-gradient(115deg, rgba(8, 12, 10, 0.78), rgba(8, 12, 10, 0.44));
  border-left: 1px solid rgba(241, 234, 217, 0.3);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}
.vitals-head { display: flex; justify-content: space-between; margin-bottom: 8px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.16em; color: var(--dim); }
.vitals-head span:last-child { color: var(--green); }
.vitals-panel.low .vitals-head span:last-child { color: var(--red); animation: dangerBlink 0.8s infinite; }
.vital-row { display: grid; grid-template-columns: 16px 1fr 34px; align-items: center; gap: 7px; margin-bottom: 5px; }
.vital-icon { font-family: var(--mono); font-size: 7px; color: var(--dim); }
.vital-track { height: 5px; background: rgba(241, 234, 217, 0.11); overflow: hidden; }
.vital-track i { display: block; height: 100%; width: 100%; transform-origin: left; transition: width 0.18s ease; }
.armor-row .vital-track i { background: linear-gradient(90deg, #3b8db9, var(--blue)); }
.health-row .vital-track i { background: linear-gradient(90deg, #d7d1bf, #fff6da); }
.vitals-panel.low .health-row .vital-track i { background: linear-gradient(90deg, #b3302b, var(--red)); }
.vital-row b { text-align: right; font-family: var(--mono); font-size: 9px; font-weight: 500; color: var(--cream); }
.vitals-foot { display: flex; align-items: center; gap: 14px; margin-top: 9px; padding-top: 8px; border-top: 1px solid var(--line-soft); font-family: var(--mono); font-size: 7px; color: var(--dim); }
.vitals-foot b { color: var(--muted); font-weight: 500; }
.vitals-foot em { font-style: normal; color: var(--cream); }
.key-hint { padding: 2px 5px; border: 1px solid var(--line); color: var(--muted); }
#kills-readout { margin-left: auto; }

.weapon-panel {
  position: absolute; right: calc(26px + var(--safe-r)); bottom: calc(26px + var(--safe-b)); width: 272px;
  text-align: right; padding: 12px 16px 10px;
  background: linear-gradient(245deg, rgba(8, 12, 10, 0.8), rgba(8, 12, 10, 0.4));
  border-right: 1px solid rgba(241, 234, 217, 0.3);
  clip-path: polygon(0 0, 100% 0, 100% 100%, 10px 100%, 0 calc(100% - 10px));
}
.weapon-head { display: flex; justify-content: flex-end; gap: 9px; align-items: center; font-family: var(--mono); font-size: 7px; letter-spacing: 0.13em; color: var(--dim); }
#fire-mode { color: var(--gold); border: 1px solid rgba(242, 193, 78, 0.36); padding: 1px 4px; }
.weapon-name { margin-top: 4px; font-size: 19px; font-weight: 700; letter-spacing: 0.13em; line-height: 1; }
.ammo-line { display: flex; justify-content: flex-end; align-items: baseline; gap: 5px; margin: 2px 0 1px; }
.ammo-line strong { font-size: 48px; line-height: 0.9; font-weight: 600; font-variant-numeric: tabular-nums; }
.ammo-line span { font-family: var(--mono); font-size: 12px; color: var(--dim); }
.ammo-line em { font-family: var(--mono); font-style: normal; font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; }
.reload-track { height: 2px; background: rgba(241, 234, 217, 0.1); margin: 6px 0 8px; opacity: 0; transition: opacity 0.2s; }
.reload-track.active { opacity: 1; }
.reload-track i { display: block; height: 100%; width: 0; background: var(--gold); }
.weapon-slots { display: flex; justify-content: flex-end; gap: 5px; }
.wslot {
  display: flex; align-items: center; gap: 6px; min-width: 92px; padding: 4px 6px;
  border: 1px solid var(--line-soft); background: rgba(241, 234, 217, 0.025);
  font-family: var(--mono); font-size: 6px; letter-spacing: 0.09em; color: var(--dim);
  text-align: left; text-transform: uppercase;
}
.wslot.active { border-color: rgba(242, 193, 78, 0.45); background: rgba(242, 193, 78, 0.07); color: var(--cream); }
.wslot b { display: grid; place-items: center; width: 14px; height: 14px; background: rgba(241, 234, 217, 0.1); color: var(--muted); font-size: 7px; font-weight: 500; }
.wslot.active b { background: var(--gold); color: #17130b; }
.wslot span { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.weapon-hint { margin-top: 7px; padding-top: 6px; border-top: 1px solid var(--line-soft); font-family: var(--mono); font-size: 6px; letter-spacing: 0.1em; color: var(--dim); }
.weapon-hint span { color: var(--gold); border: 1px solid rgba(242, 193, 78, 0.25); padding: 0 3px; margin-left: 5px; }

.build-bar {
  position: absolute; left: 50%; bottom: calc(26px + var(--safe-b)); transform: translateX(-50%);
