.toast.red strong { color: var(--red); }
.toast.blue strong { color: var(--blue); }
.toast.out { animation: toastOut 0.35s ease both; }
@keyframes toastIn { from { opacity: 0; transform: translateY(7px); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-5px); } }

.control-hint {
  position: absolute; left: 50%; bottom: 5px; transform: translateX(-50%);
  font-family: var(--mono); font-size: 6px; letter-spacing: 0.08em; color: rgba(241, 234, 217, 0.32);
  white-space: nowrap; transition: opacity 1.2s; pointer-events: none;
}
