/* ---------------- touch controls ---------------- */

.touch-ui { display: none; }
body.touch .touch-ui { display: block; position: absolute; inset: 0; pointer-events: none; }
body.touch .weapon-hint, body.touch .control-hint { display: none; }

.joystick {
