  return tmin;
}

function groundAtHeight(x, z, raw) {
  const d = Math.hypot(x, z);
  let h = raw;
  if (d > 206) h -= (d - 206) * 0.175;
  return Math.max(-3.4, h);
}

export class World {
  constructor(scene, seed = 20261031) {
    this.scene = scene;
    this.rng = mulberry32(seed);
    this.root = new THREE.Group();
    this.root.name = 'world';
    scene.add(this.root);
    this.staticGroup = new THREE.Group();
    this.root.add(this.staticGroup);
    this.propGroup = new THREE.Group();
    this.root.add(this.propGroup);
    this.dynamicGroup = new THREE.Group();
    this.root.add(this.dynamicGroup);

    this.colliders = [];
    this.surfaces = [];
    this.buildings = [];
    this.lootSpots = [];
    this.botSpawns = [];
    this.loot = [];
    this.clouds = [];
    this.batches = new Map();
    this.builtPieces = [];

    this.sites = SITES.map(site => {
      const s = { ...site };
      s.h = groundAtHeight(s.x, s.z, this.rawHeight(s.x, s.z));
      return s;
    });
    this.flatteners = this.sites;

    const byName = Object.fromEntries(this.sites.map(s => [s.name, s]));
    this.roadSegments = ROAD_LINKS.map(([a, b]) => ({
      ax: byName[a].x, az: byName[a].z, bx: byName[b].x, bz: byName[b].z,
    }));

    this.palette = {
      grassA: new THREE.Color('#5c7b45'),
      grassB: new THREE.Color('#7c9252'),
      grassC: new THREE.Color('#93a05c'),
      dry: new THREE.Color('#a6a06c'),
      sand: new THREE.Color('#cdb887'),
      wetSand: new THREE.Color('#9d8e68'),
      rock: new THREE.Color('#747768'),
      rockDark: new THREE.Color('#565b50'),
      dirt: new THREE.Color('#8d7c59'),
      road: new THREE.Color('#a08a61'),
      underwater: new THREE.Color('#5e6a5c'),
    };
    this.tmpColor = new THREE.Color();
    this.spreadColor = new THREE.Color();

    this.createMaterials();
    this.createEnvironment();
    this.createTerrain();
    this.createWater();
    this.createClouds();
    this.createPlane();

    buildStructures(this);
    this.finalizeStatic();
    this.createVegetation();
    populateLoot(this);
    this.mapCanvas = createMapCanvas(this);
    this.generateBotSpawns();

    this.time = 0;
    this.planeTime = -9;
    this.zoneRing = null;
  }

  rawHeight(x, z) {
    const d = Math.hypot(x, z);
    let h = 3.1;
    h += 5.4 * Math.sin(x * 0.021 + 0.4) * Math.cos(z * 0.019 - 0.3);
    h += 3.0 * Math.sin(x * 0.047 - 1.2) * Math.cos(z * 0.041 + 0.8);
    h += 1.1 * Math.sin((x + z) * 0.09);
    h += 9.2 * Math.exp(-(((x - 26) ** 2) + ((z + 86) ** 2)) / 4700);
    h += 6.4 * Math.exp(-(((x + 122) ** 2) + ((z - 92) ** 2)) / 5400);
    h += 4.2 * Math.exp(-(((x - 142) ** 2) + ((z - 32) ** 2)) / 4200);
    h += 3.2 * Math.exp(-(((x - 36) ** 2) + ((z - 42) ** 2)) / 2600);
    if (d > 206) h -= (d - 206) * 0.175;
    return Math.max(-3.4, h);
  }

  terrainHeight(x, z) {
    let h = this.rawHeight(x, z);
    for (const s of this.flatteners) {
      const d = Math.hypot(x - s.x, z - s.z);
      if (d < s.r) {
        const w = 1 - smoothstep(s.r * 0.56, s.r, d);
        h = h * (1 - w) + s.h * w;
      }
    }
    return h;
  }

  surfaceHeight(x, z, feetY) {
    let top = this.terrainHeight(x, z);
    const limit = feetY + 0.7;
    for (const s of this.surfaces) {
      if (!s) continue;
      const dx = x - s.x, dz = z - s.z;
      const c = Math.cos(-s.ry), sn = Math.sin(-s.ry);
      const lx = dx * c - dz * sn;
      const lz = dx * sn + dz * c;
      if (Math.abs(lx) > s.w / 2 || Math.abs(lz) > s.d / 2) continue;
      let y = s.y;
      if (s.type === 'ramp') y = s.y + (s.d / 2 - lz) / s.d * s.rise;
      if (y > top && y <= limit) top = y;
    }
    return top;
  }

  addCollider(cx, cy, cz, w, h, d) {
    this.colliders.push({
      minX: cx - w / 2, maxX: cx + w / 2,
      minY: cy - h / 2, maxY: cy + h / 2,
      minZ: cz - d / 2, maxZ: cz + d / 2,
    });
  }

  addSurface(surface) {
    this.surfaces.push(surface);
  }

  createMaterials() {
    const mat = (color, options = {}) => new THREE.MeshStandardMaterial({
      color, roughness: 0.85, metalness: 0.05, ...options,
    });
    this.materials = {
      plaster: mat(0xc9bda2),
      plasterWarm: mat(0xd4c4a0),
      plasterCool: mat(0xb3b1a2),
      brick: mat(0x9b5e47),
      wood: mat(0x795538),
      woodDark: mat(0x4f3827),
      roof: mat(0x7d4233),
      roofDark: mat(0x583029),
      roofMetal: mat(0x64706a, { metalness: 0.35, roughness: 0.62 }),
      metal: mat(0x707b74, { metalness: 0.4, roughness: 0.55 }),
      metalDark: mat(0x414b47, { metalness: 0.35, roughness: 0.6 }),
      containerRed: mat(0xa14c3c, { metalness: 0.25, roughness: 0.65 }),
      containerBlue: mat(0x3d6873, { metalness: 0.25, roughness: 0.65 }),
      containerGreen: mat(0x5b7050, { metalness: 0.25, roughness: 0.65 }),
      concrete: mat(0x97968a, { roughness: 0.96 }),
      concreteDark: mat(0x71736a, { roughness: 0.98 }),
      glass: mat(0x20363b, { roughness: 0.24, metalness: 0.4, emissive: 0x091417, emissiveIntensity: 0.75 }),
      sandbag: mat(0x99895f),
      trim: mat(0xd8cdb4),
      rust: mat(0x8a5a3f, { metalness: 0.2, roughness: 0.8 }),
      gable: mat(0xc7b99b, { side: THREE.DoubleSide }),
      gableWood: mat(0x735034, { side: THREE.DoubleSide }),
      hay: mat(0xc6a85c),
      black: mat(0x181c19),
      white: mat(0xe7dfcc),
    };
  }

  batch(matKey, geometry, matrix) {
    const g = geometry;
    if (matrix) g.applyMatrix4(matrix);
    let list = this.batches.get(matKey);
    if (!list) { list = []; this.batches.set(matKey, list); }
    list.push(g);
  }

  addBox(matKey, w, h, d, x, y, z, ry = 0, rx = 0, rz = 0) {
    const geo = new THREE.BoxGeometry(w, h, d);
    const quat = new THREE.Quaternion().setFromEuler(new THREE.Euler(rx, ry, rz));
    const m = new THREE.Matrix4().compose(new THREE.Vector3(x, y, z), quat, new THREE.Vector3(1, 1, 1));
    this.batch(matKey, geo, m);
    return this;
  }

  addCylinder(matKey, rTop, rBottom, height, segments, x, y, z, rx = 0, ry = 0, rz = 0) {
    const geo = new THREE.CylinderGeometry(rTop, rBottom, height, segments);
    const quat = new THREE.Quaternion().setFromEuler(new THREE.Euler(rx, ry, rz));
    const m = new THREE.Matrix4().compose(new THREE.Vector3(x, y, z), quat, new THREE.Vector3(1, 1, 1));
    this.batch(matKey, geo, m);
    return this;
  }

  addTriangle(matKey, points) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(points.flat(), 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute([0, 0, 1, 0, 0, 1], 2));
    geo.computeVertexNormals();
    this.batch(matKey, geo);
    return this;
  }

  addLootSpot(x, z, site) {
    this.lootSpots.push({ x, z, site });
    return this;
  }

  addSpawn(x, z) {
    this.botSpawns.push({ x, z });
  }

  finalizeStatic() {
    for (const [matKey, list] of this.batches) {
      if (!list.length) continue;
      const merged = mergeGeometries(list, false);
      if (!merged) continue;
      const mesh = new THREE.Mesh(merged, this.materials[matKey] || this.materials.plaster);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      mesh.matrixAutoUpdate = false;
      mesh.updateMatrix();
      this.staticGroup.add(mesh);
      for (const geo of list) geo.dispose();
    }
    this.batches.clear();
  }

  createEnvironment() {
    const hemi = new THREE.HemisphereLight(0xb9d6e8, 0x6c603e, 0.95);
    this.scene.add(hemi);

    const ambient = new THREE.AmbientLight(0xfff4df, 0.16);
    this.scene.add(ambient);

    const sun = new THREE.DirectionalLight(0xffd2a0, 2.35);
    sun.position.set(80, 120, 55);
    sun.castShadow = true;
    sun.shadow.mapSize.set(1536, 1536);
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 320;
    sun.shadow.camera.left = -68;
    sun.shadow.camera.right = 68;
    sun.shadow.camera.top = 68;
    sun.shadow.camera.bottom = -68;
    sun.shadow.bias = -0.0006;
    sun.shadow.normalBias = 0.035;
    this.scene.add(sun);
    this.scene.add(sun.target);
    this.sun = sun;

    this.scene.fog = new THREE.Fog(0xd8c2a4, 128, 430);

    const skyGeo = new THREE.SphereGeometry(620, 32, 20);
    const skyMat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        sunDir: { value: new THREE.Vector3(0.42, 0.55, 0.3).normalize() },
        topColor: { value: new THREE.Color('#537fa5') },
        horizonColor: { value: new THREE.Color('#e8c49d') },
        hazeColor: { value: new THREE.Color('#f5d9b4') },
      },
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        varying vec3 vDir;
        uniform vec3 sunDir;
        uniform vec3 topColor;
        uniform vec3 horizonColor;
        uniform vec3 hazeColor;
        void main() {
          float h = normalize(vDir).y;
          vec3 col = mix(horizonColor, topColor, smoothstep(-0.03, 0.72, h));
          col = mix(hazeColor, col, smoothstep(-0.16, 0.06, h));
          float sunDot = max(dot(normalize(vDir), normalize(sunDir)), 0.0);
          col += vec3(1.0, 0.78, 0.48) * pow(sunDot, 9.0) * 0.28;
          col += vec3(1.0, 0.92, 0.68) * pow(sunDot, 900.0) * 2.2;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    this.sky = new THREE.Mesh(skyGeo, skyMat);
    this.sky.frustumCulled = false;
    this.scene.add(this.sky);
  }

  createTerrain() {
    const segments = 184;
    const geo = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE, segments, segments);
    geo.rotateX(-Math.PI / 2);
    const pos = geo.attributes.position;
    const colors = new Float32Array(pos.count * 3);
    const p = this.palette;
    const color = new THREE.Color();
    const rockColor = new THREE.Color();

    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i);
      const z = pos.getZ(i);
      const h = this.terrainHeight(x, z);
      pos.setY(i, h);

      const hx = this.terrainHeight(x + 1.7, z);
      const hz = this.terrainHeight(x, z + 1.7);
      const slope = (Math.abs(h - hx) + Math.abs(h - hz)) / 1.7;
      const n = Math.sin(x * 0.73 + z * 1.11) * 0.5 + 0.5;
      const n2 = Math.sin(x * 0.17 - z * 0.23) * 0.5 + 0.5;

      color.copy(p.grassA).lerp(p.grassB, n * 0.7 + n2 * 0.3);
      if (n2 > 0.67) color.lerp(p.grassC, 0.35);
      if (n < 0.32 && h > 1.8) color.lerp(p.dry, 0.25);

      if (h < -0.4) color.copy(p.underwater);
      else if (h < 0.9) color.copy(p.wetSand).lerp(p.sand, (h + 0.4) / 1.3);
      else if (h < 1.8) color.copy(p.sand).lerp(p.dry, 0.3);

      if (h > 1.5 && slope > 0.92) {
        rockColor.copy(p.rock).lerp(p.rockDark, Math.min(1, (slope - 0.9) * 0.7));
        color.lerp(rockColor, Math.min(0.86, (slope - 0.9) * 0.95));
      }

      let roadDist = 99;
      for (const s of this.roadSegments) {
        const d = distToSegment(x, z, s.ax, s.az, s.bx, s.bz);
        if (d < roadDist) roadDist = d;
      }
      if (roadDist < 7.2) {
        const w = 1 - smoothstep(3.7, 7.2, roadDist);
        color.lerp(p.road, w * 0.55);
      }

      for (const site of this.sites) {
        const d = Math.hypot(x - site.x, z - site.z);
        if (d < site.r * 0.82) {
          const w = 1 - smoothstep(site.r * 0.35, site.r * 0.82, d);
          color.lerp(p.dirt, w * 0.28);
        }
      }

      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
    }

    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geo.computeVertexNormals();
    const mat = new THREE.MeshStandardMaterial({
      vertexColors: true, roughness: 0.97, metalness: 0.0, flatShading: true,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.receiveShadow = true;
    mesh.name = 'terrain';
    this.terrain = mesh;
    this.root.add(mesh);
  }

  createWater() {
    const geo = new THREE.CircleGeometry(720, 72);
    geo.rotateX(-Math.PI / 2);
    const mat = new THREE.MeshStandardMaterial({
      color: 0x2f7281, roughness: 0.26, metalness: 0.32,
      transparent: true, opacity: 0.92,
    });
    const water = new THREE.Mesh(geo, mat);
    water.position.y = -1.35;
    water.receiveShadow = false;
    this.water = water;
    this.root.add(water);

    const deepGeo = new THREE.CircleGeometry(760, 48);
    deepGeo.rotateX(-Math.PI / 2);
    const deep = new THREE.Mesh(deepGeo, new THREE.MeshBasicMaterial({ color: 0x194a56 }));
    deep.position.y = -2.2;
    this.root.add(deep);
  }

  createClouds() {
    const cloudMat = new THREE.MeshBasicMaterial({
      color: 0xfff4df, transparent: true, opacity: 0.55, depthWrite: false, fog: false,
    });
    const blob = new THREE.IcosahedronGeometry(1, 0);
    for (let i = 0; i < 11; i++) {
      const group = new THREE.Group();
      const count = 3 + Math.floor(this.rng() * 4);
      for (let j = 0; j < count; j++) {
        const mesh = new THREE.Mesh(blob, cloudMat);
        const s = 8 + this.rng() * 13;
        mesh.scale.set(s, s * (0.32 + this.rng() * 0.2), s * (0.7 + this.rng() * 0.5));
        mesh.position.set((this.rng() - 0.5) * 38, (this.rng() - 0.5) * 5, (this.rng() - 0.5) * 18);
        group.add(mesh);
      }
      const angle = this.rng() * Math.PI * 2;
      const dist = 100 + this.rng() * 310;
      group.position.set(Math.cos(angle) * dist, 82 + this.rng() * 38, Math.sin(angle) * dist);
      group.userData.speed = 0.5 + this.rng() * 0.8;
      this.clouds.push(group);
      this.root.add(group);
    }
  }

  createPlane() {
    const group = new THREE.Group();
    const bodyMat = new THREE.MeshStandardMaterial({ color: 0x6e765f, roughness: 0.66, metalness: 0.18 });
    const wingMat = new THREE.MeshStandardMaterial({ color: 0x56604f, roughness: 0.7, metalness: 0.15 });
    const darkMat = new THREE.MeshStandardMaterial({ color: 0x2b332f, roughness: 0.7 });
    const add = (geo, mat, x, y, z) => {
      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(x, y, z);
      group.add(mesh);
      return mesh;
    };
    add(new THREE.BoxGeometry(13, 2.1, 2.2), bodyMat, 0, 0, 0);
    add(new THREE.BoxGeometry(3.4, 1.4, 1.9), bodyMat, 6.4, -0.2, 0);
    add(new THREE.BoxGeometry(2.2, 0.5, 18), wingMat, -0.4, 0.35, 0);
    add(new THREE.BoxGeometry(2.6, 0.45, 7), wingMat, -5.7, 0.55, 0);
    add(new THREE.BoxGeometry(0.4, 2.2, 5), wingMat, -6.5, 1.1, 0);
    add(new THREE.BoxGeometry(0.5, 0.28, 15), darkMat, -0.4, 0.65, 0);
    const props = [];
    for (const side of [-1, 1]) {
      add(new THREE.CylinderGeometry(0.55, 0.55, 2.2, 8).rotateZ(Math.PI / 2), darkMat, 0.4, -0.1, side * 5.7);
      const prop = add(new THREE.BoxGeometry(0.1, 2.6, 0.24), darkMat, 1.7, -0.1, side * 5.7);
      props.push(prop);
    }
    const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.18, 6, 4), new THREE.MeshBasicMaterial({ color: 0xff4030 }));
    beacon.position.set(-2, 1.4, 0);
    group.add(beacon);
    group.position.set(-420, 152, 40);
    group.scale.setScalar(1.1);
    this.plane = { group, props, beacon };
    this.root.add(group);
  }

  generateBotSpawns() {
    for (const site of this.sites) {
      for (let i = 0; i < 7; i++) {
        const a = (i / 7) * Math.PI * 2 + this.rng() * 0.5;
        const r = site.r * (0.62 + this.rng() * 0.3);
        const x = site.x + Math.cos(a) * r;
        const z = site.z + Math.sin(a) * r;
        if (this.terrainHeight(x, z) > 0.6) this.addSpawn(x, z);
      }
    }
    for (let i = 0; i < 26; i++) {
      const a = this.rng() * Math.PI * 2;
      const r = 28 + this.rng() * 175;
      const x = Math.cos(a) * r;
      const z = Math.sin(a) * r;
      if (this.terrainHeight(x, z) > 0.8) this.addSpawn(x, z);
    }
  }

  placeLoot(type, weaponId, x, z, yOverride) {
    const group = buildPickupModel(type, weaponId);
    const baseY = yOverride ?? this.terrainHeight(x, z);
    group.position.set(x, baseY + 0.02, z);
    group.rotation.y = this.rng() * Math.PI * 2;
    this.root.add(group);
    const weapon = weaponId ? WEAPONS[weaponId] : null;
    const item = {
      type, weaponId, group, baseY, x, z,
      phase: this.rng() * Math.PI * 2,
      taken: false,
      label: type === 'weapon' ? weapon?.name || 'WEAPON' : type === 'ammo' ? 'AMMUNITION' : type === 'med' ? 'FIELD MEDKIT' : 'BALLISTIC PLATE',
      detail: type === 'weapon' ? weapon?.typeLabel || '' : type === 'ammo' ? 'RESERVE AMMO' : type === 'med' ? '+45 HEALTH' : '+50 ARMOR',
    };
    this.loot.push(item);
    return item;
  }

  removeLoot(item) {
    if (!item || item.taken) return;
    item.taken = true;
    item.group.visible = false;
  }

  nearestLoot(pos, radius = 2.2) {
    let best = null;
    let bestD = radius * radius;
    for (const item of this.loot) {
      if (item.taken) continue;
      const dx = pos.x - item.group.position.x;
      const dz = pos.z - item.group.position.z;
      const dy = pos.y - item.group.position.y;
      const d = dx * dx + dz * dz + dy * dy * 0.6;
      if (d < bestD) { bestD = d; best = item; }
    }
    return best;
  }

  nearestSite(x, z) {
    let best = null, bestD = Infinity;
    for (const s of this.sites) {
      const d = Math.hypot(x - s.x, z - s.z);
      if (d < bestD) { bestD = d; best = s; }
    }
    return { site: best, distance: bestD };
  }

  worldToMap(x, z, size) {
    const s = size / (MAP_EXTENT * 2);
    return [size * 0.5 + x * s, size * 0.5 + z * s];
  }

  raycastStatic(origin, dir, maxDist) {
    let best = null;
    for (const box of this.colliders) {
      const t = rayAabb(origin, dir, box, maxDist);
      if (t !== null && t >= 0 && t < maxDist && (!best || t < best.distance)) {
        best = { distance: t, box };
      }
    }
    if (best) {
      best.point = {
        x: origin.x + dir.x * best.distance,
        y: origin.y + dir.y * best.distance,
        z: origin.z + dir.z * best.distance,
      };
      return best;
    }
    return null;
  }

  raycast(origin, dir, maxDist = 300) {
    const staticHit = this.raycastStatic(origin, dir, maxDist);
    let best = staticHit || null;
    let terrainHit = null;
    const step = 2.2;
    for (let t = 0.5; t < maxDist; t += step) {
      const x = origin.x + dir.x * t;
      const y = origin.y + dir.y * t;
      const z = origin.z + dir.z * t;
      const h = this.terrainHeight(x, z);
      if (y <= h) {
        terrainHit = {
          distance: t,
          point: { x, y: h, z },
          kind: 'terrain',
        };
        break;
      }
    }
    if (terrainHit && (!best || terrainHit.distance < best.distance)) best = terrainHit;
    return best;
  }

  lineBlocked(a, b) {
    const dx = b.x - a.x, dy = b.y - a.y, dz = b.z - a.z;
    const len = Math.hypot(dx, dy, dz);
    if (len < 0.01) return false;
    const dir = { x: dx / len, y: dy / len, z: dz / len };
    const hit = this.raycastStatic(a, dir, len * 0.96);
    if (hit) return true;
    const steps = Math.max(3, Math.ceil(len / 9));
    for (let i = 1; i < steps; i++) {
      const t = (i / steps) * len;
      const y = a.y + dy * (i / steps);
      if (y < this.terrainHeight(a.x + dx * (i / steps), a.z + dz * (i / steps)) + 0.12) return true;
    }
    return false;
  }

  resolveCircle(pos, radius, height = 1.8) {
    const feet = pos.y;
    const head = pos.y + height;
    for (let iteration = 0; iteration < 2; iteration++) {
      for (const box of this.colliders) {
        if (head < box.minY + 0.08 || feet > box.maxY - 0.08) continue;
        const cx = Math.max(box.minX, Math.min(pos.x, box.maxX));
        const cz = Math.max(box.minZ, Math.min(pos.z, box.maxZ));
        let dx = pos.x - cx;
        let dz = pos.z - cz;
        const d2 = dx * dx + dz * dz;
        if (d2 > radius * radius) continue;
        if (d2 > 0.000001) {
          const d = Math.sqrt(d2);
          const push = radius - d;
          pos.x += (dx / d) * push;
          pos.z += (dz / d) * push;
        } else {
          const toLeft = pos.x - box.minX;
          const toRight = box.maxX - pos.x;
          const toBack = pos.z - box.minZ;
          const toFront = box.maxZ - pos.z;
          const min = Math.min(toLeft, toRight, toBack, toFront);
          if (min === toLeft) pos.x = box.minX - radius;
          else if (min === toRight) pos.x = box.maxX + radius;
          else if (min === toBack) pos.z = box.minZ - radius;
          else pos.z = box.maxZ + radius;
        }
      }
    }
    const d = Math.hypot(pos.x, pos.z);
    if (d > ISLAND_RADIUS - 2) {
      const s = (ISLAND_RADIUS - 2) / d;
      pos.x *= s;
      pos.z *= s;
    }
    return pos;
  }

  resetPlane() {
    this.planeTime = -16;
  }

  update(dt, elapsed, playerPos, camera) {
    this.time = elapsed;
    const sun = this.sun;
    if (playerPos) {
      sun.position.set(playerPos.x + 74, 118, playerPos.z + 48);
      sun.target.position.set(playerPos.x, 0, playerPos.z);
      sun.target.updateMatrixWorld();
    }
    if (camera && this.sky) this.sky.position.copy(camera.position);

    this.water.position.y = -1.35 + Math.sin(elapsed * 0.7) * 0.035;

    for (const cloud of this.clouds) {
      cloud.position.x += cloud.userData.speed * dt;
      if (cloud.position.x > 430) cloud.position.x = -430;
    }

    for (const item of this.loot) {
      if (item.taken) continue;
      const t = elapsed * 2.1 + item.phase;
      item.group.position.y = item.baseY + 0.02 + Math.sin(t) * 0.04;
      const ring = item.group.userData.ring;
      if (ring) ring.rotation.z = elapsed * 0.9 + item.phase;
      const beam = item.group.userData.beam;
      if (beam) beam.material.opacity = 0.055 + Math.sin(t * 0.7) * 0.018;
    }

    this.planeTime += dt;
    const plane = this.plane;
    if (plane) {
      const span = 900;
      const x = -440 + ((this.planeTime * 19 + 170) % span);
      plane.group.position.set(x, 152, 46);
      plane.group.rotation.z = Math.sin(elapsed * 0.5) * 0.02;
      plane.group.rotation.x = Math.sin(elapsed * 0.37) * 0.012;
      for (const prop of plane.props) prop.rotation.x += dt * 38;
      plane.beacon.material.color.setHex(Math.sin(elapsed * 3) > 0 ? 0xff4030 : 0x52120e);
    }

    if (this.beacon) {
      this.beacon.material.emissiveIntensity = 0.3 + (Math.sin(elapsed * 2.6) > 0.6 ? 2.4 : 0);
    }
  }
}

import * as THREE from 'three';

const UP = new THREE.Vector3(0, 1, 0);

function beam(world, mat, x1, y1, z1, x2, y2, z2, thickness = 0.14) {
  const dx = x2 - x1, dy = y2 - y1, dz = z2 - z1;
  const length = Math.hypot(dx, dy, dz);
  const geo = new THREE.BoxGeometry(thickness, length, thickness);
  const dir = new THREE.Vector3(dx, dy, dz).normalize();
  const quat = new THREE.Quaternion().setFromUnitVectors(UP, dir);
  const m = new THREE.Matrix4().compose(
    new THREE.Vector3((x1 + x2) / 2, (y1 + y2) / 2, (z1 + z2) / 2),
    quat,
    new THREE.Vector3(1, 1, 1),
  );
  world.batch(mat, geo, m);
}

function localToWorld(cx, cz, ry, lx, lz) {
  const c = Math.cos(ry), s = Math.sin(ry);
  return [cx + lx * c + lz * s, cz - lx * s + lz * c];
}

function makeCrate(world, x, z, size = 1.1, ry = 0, site = null) {
  const y0 = world.terrainHeight(x, z);
  world.addBox('wood', size, size * 0.82, size, x, y0 + size * 0.41, z, ry);
  world.addBox('woodDark', size * 1.02, 0.07, size * 0.14, x, y0 + size * 0.82, z, ry);
  world.addBox('woodDark', size * 0.14, 0.07, size * 1.02, x, y0 + size * 0.82, z, ry);
  world.addCollider(x, y0 + size * 0.41, z, size, size * 0.82, size);
  if (site) world.addLootSpot(x + 1.1, z, site);
}

function makeBarrel(world, x, z, color = 'rust') {
  const y0 = world.terrainHeight(x, z);
  world.addCylinder(color, 0.44, 0.44, 1.15, 8, x, y0 + 0.575, z);
  world.addCylinder('metalDark', 0.46, 0.46, 0.07, 8, x, y0 + 0.9, z);
  world.addCylinder('metalDark', 0.46, 0.46, 0.07, 8, x, y0 + 0.28, z);
  world.addCollider(x, y0 + 0.575, z, 0.88, 1.15, 0.88);
}

function makeSandbags(world, x, z, ry, length = 4.2) {
  const y0 = world.terrainHeight(x, z);
  const c = Math.cos(ry), s = Math.sin(ry);
  const count = Math.max(2, Math.round(length / 0.95));
  for (let row = 0; row < 2; row++) {
    const offset = row % 2 ? 0.46 : 0;
    for (let i = 0; i < count; i++) {
      const t = (i + 0.5) / count - 0.5;
      const lx = t * length;
      const lz = offset;
      world.addBox('sandbag', 0.94, 0.42, 0.62, x + lx * c + lz * s, y0 + 0.21 + row * 0.4, z - lx * s + lz * c, ry);
    }
  }
  const w = Math.abs(c) > 0.5 ? length : 0.95;
  const d = Math.abs(c) > 0.5 ? 0.95 : length;
  world.addCollider(x, y0 + 0.42, z, w, 0.84, d);
}

function makeContainer(world, x, z, ry = 0, color = 'containerRed') {
  const y0 = world.terrainHeight(x, z);
  const w = 6.2, h = 2.62, d = 2.55;
  world.addBox(color, w, h, d, x, y0 + h / 2, z, ry);
  const c = Math.cos(ry), s = Math.sin(ry);
  for (let i = 0; i < 7; i++) {
    const lx = -w / 2 + 0.35 + i * ((w - 0.7) / 6);
    for (const lz of [-d / 2 - 0.03, d / 2 + 0.03]) {
      world.addBox('metalDark', 0.1, h * 0.92, 0.08, x + lx * c + lz * s, y0 + h / 2, z - lx * s + lz * c, ry);
    }
  }
  for (const lz of [-d / 2 - 0.04, d / 2 + 0.04]) {
    world.addBox('rust', w, 0.12, 0.12, x + lz * s, y0 + 0.08, z + lz * c, ry);
    world.addBox('rust', w, 0.12, 0.12, x + lz * s, y0 + h - 0.08, z + lz * c, ry);
  }
  world.addBox('metalDark', 0.18, h * 0.8, 0.16, x - (w / 2) * c, y0 + h / 2, z + (w / 2) * s, ry);
  const cw = Math.abs(c) > 0.5 ? w : d;
  const cd = Math.abs(c) > 0.5 ? d : w;
  world.addCollider(x, y0 + h / 2, z, cw, h, cd);
  world.addLootSpot(x + Math.cos(ry + Math.PI / 2) * 2.2, z - Math.sin(ry + Math.PI / 2) * 2.2, null);
}

function doorSideGeometry(side, x, z, w, d, doorW, doorH, h, y0, wallMat, trimMat, awningMat) {
  const t = 0.28;
  const alongX = side === 'north' || side === 'south';
  const len = alongX ? w : d;
  const off = alongX ? (side === 'south' ? d / 2 : -d / 2) : (side === 'east' ? w / 2 : -w / 2);
  const seg = Math.max(0, (len - doorW) / 2);
  const axisOffset = (doorW / 2 + seg / 2);

  const piece = (place, width, height, cy) => {
    if (width <= 0.04) return;
    if (alongX) {
      worldBox(worldRef, wallMat, width, height, t, x + place, cy, z + off);
    } else {
      worldBox(worldRef, wallMat, t, height, width, x + off, cy, z + place);
    }
  };
  const worldRef = currentWorld;
  if (seg > 0.18) {
    piece(-axisOffset, seg, h, y0 + h / 2);
    piece(axisOffset, seg, h, y0 + h / 2);
    if (alongX) {
      currentWorld.addCollider(x - axisOffset, y0 + h / 2, z + off, seg, h, t);
      currentWorld.addCollider(x + axisOffset, y0 + h / 2, z + off, seg, h, t);
    } else {
      currentWorld.addCollider(x + off, y0 + h / 2, z - axisOffset, t, h, seg);
      currentWorld.addCollider(x + off, y0 + h / 2, z + axisOffset, t, h, seg);
    }
  }
  const lintelH = h - doorH;
  if (lintelH > 0.1) {
    if (alongX) worldBox(worldRef, wallMat, doorW, lintelH, t, x, y0 + doorH + lintelH / 2, z + off);
    else worldBox(worldRef, wallMat, t, lintelH, doorW, x + off, y0 + doorH + lintelH / 2, z);
  }

  const postT = 0.13;
  if (alongX) {
    worldBox(worldRef, trimMat, postT, doorH, t + 0.12, x - doorW / 2, y0 + doorH / 2, z + off);
    worldBox(worldRef, trimMat, postT, doorH, t + 0.12, x + doorW / 2, y0 + doorH / 2, z + off);
    worldBox(worldRef, trimMat, doorW + 0.3, 0.14, t + 0.14, x, y0 + doorH, z + off);
  } else {
    worldBox(worldRef, trimMat, t + 0.12, doorH, postT, x + off, y0 + doorH / 2, z - doorW / 2);
    worldBox(worldRef, trimMat, t + 0.12, doorH, postT, x + off, y0 + doorH / 2, z + doorW / 2);
    worldBox(worldRef, trimMat, t + 0.14, 0.14, doorW + 0.3, x + off, y0 + doorH, z);
  }

  const outward = alongX ? (side === 'south' ? 1 : -1) : (side === 'east' ? 1 : -1);
  if (alongX) {
    worldBox(worldRef, awningMat, doorW + 1.1, 0.12, 1.15, x, y0 + doorH + 0.2, z + off + outward * 0.56);
    worldBox(worldRef, trimMat, doorW + 1.0, 0.12, 0.12, x, y0 + doorH + 0.42, z + off + outward * 1.06);
  } else {
    worldBox(worldRef, awningMat, 1.15, 0.12, doorW + 1.1, x + off + outward * 0.56, y0 + doorH + 0.2, z);
    worldBox(worldRef, trimMat, 0.12, 0.12, doorW + 1.0, x + off + outward * 1.06, y0 + doorH + 0.42, z);
  }
  worldBox(worldRef, 'concreteDark', alongX ? doorW + 0.7 : 1.0, 0.16, alongX ? 1.0 : doorW + 0.7,
    x + (alongX ? 0 : outward * 0.45), y0 + 0.08, z + (alongX ? outward * 0.45 : 0));
}

let currentWorld = null;
function worldBox(world, mat, w, h, d, x, y, z, ry = 0, rx = 0, rz = 0) {
  world.addBox(mat, w, h, d, x, y, z, ry, rx, rz);
}

function makeBuilding(world, opts) {
  const {
    x, z, w, d, h = 3.3, door = 'south', doorWidth = 2.05, doorHeight = 2.35,
    roof = 'gable', wall = 'plaster', roofMat = 'roof', windows = true,
    site = null, ruined = false, trim = 'trim', bigDoor = false,
  } = opts;
  currentWorld = world;
  const y0 = world.terrainHeight(x, z);
  const t = 0.28;

  world.addBox('concreteDark', w + 0.35, 0.12, d + 0.35, x, y0 + 0.02, z);

  const sides = {
    north: { alongX: true, off: -d / 2, len: w },
    south: { alongX: true, off: d / 2, len: w },
    west: { alongX: false, off: -w / 2, len: d },
    east: { alongX: false, off: w / 2, len: d },
  };

  for (const [side, s] of Object.entries(sides)) {
    if (ruined && (side === 'north' || side === 'east') && Math.sin(x * 0.7 + z * 0.3 + side.length) > 0.1) continue;
    if (side === door) {
      const dw = Math.min(bigDoor ? 3.8 : doorWidth, s.len - 1.2);
      doorSideGeometry(side, x, z, w, d, dw, bigDoor ? Math.min(doorHeight + 0.6, h - 0.2) : doorHeight, h, y0, wall, trim, roofMat);
      continue;
    }

    if (s.alongX) {
      world.addBox(wall, s.len, h, t, x, y0 + h / 2, z + s.off);
      world.addCollider(x, y0 + h / 2, z + s.off, s.len, h, t);
    } else {
      world.addBox(wall, t, h, s.len, x + s.off, y0 + h / 2, z);
      world.addCollider(x + s.off, y0 + h / 2, z, t, h, s.len);
    }

    if (windows && !ruined) {
      const count = s.len > 8 ? 2 : 1;
      const positions = count === 2 ? [-s.len * 0.26, s.len * 0.26] : [0];
      const outward = s.alongX ? (side === 'north' ? -1 : 1) : (side === 'east' ? 1 : -1);
      for (const pos of positions) {
        const wx = s.alongX ? x + pos : x + s.off + outward * (t / 2 + 0.035);
        const wz = s.alongX ? z + s.off + outward * (t / 2 + 0.035) : z + pos;
        if (s.alongX) {
          world.addBox(trim, 1.55, 1.22, 0.09, wx, y0 + 1.62, wz);
          world.addBox('glass', 1.2, 0.88, 0.11, wx, y0 + 1.62, wz + outward * 0.02);
          world.addBox(trim, 0.07, 0.98, 0.1, wx, y0 + 1.62, wz + outward * 0.04);
        } else {
          world.addBox(trim, 0.09, 1.22, 1.55, wx, y0 + 1.62, wz);
          world.addBox('glass', 0.11, 0.88, 1.2, wx + outward * 0.02, y0 + 1.62, wz);
          world.addBox(trim, 0.1, 0.98, 0.07, wx + outward * 0.04, y0 + 1.62, wz);
        }
      }
    }
  }

  if (!ruined) {
    if (roof === 'gable') {
      const rise = Math.min(2.5, w * 0.22);
      const half = d / 2 + 0.48;
      const slope = Math.hypot(half, rise);
      const angle = Math.atan2(rise, half);
      world.addBox(roofMat, w + 0.9, 0.24, slope, x, y0 + h + rise / 2, z - (d / 4 + 0.24), 0, -angle, 0);
      world.addBox(roofMat, w + 0.9, 0.24, slope, x, y0 + h + rise / 2, z + (d / 4 + 0.24), 0, angle, 0);
      world.addBox('woodDark', w + 1.0, 0.17, 0.28, x, y0 + h + rise + 0.03, z);
      const gableMat = wall === 'wood' ? 'gableWood' : 'gable';
      world.addTriangle(gableMat, [
        [x - w / 2, y0 + h, z - d / 2], [x - w / 2, y0 + h, z + d / 2], [x - w / 2, y0 + h + rise, z],
      ]);
      world.addTriangle(gableMat, [
        [x + w / 2, y0 + h, z + d / 2], [x + w / 2, y0 + h, z - d / 2], [x + w / 2, y0 + h + rise, z],
      ]);
    } else {
      world.addBox(roofMat, w + 0.8, 0.26, d + 0.8, x, y0 + h + 0.13, z);
      world.addBox(wall, w + 0.9, 0.5, 0.18, x, y0 + h + 0.42, z - d / 2 - 0.4);
      world.addBox(wall, w + 0.9, 0.5, 0.18, x, y0 + h + 0.42, z + d / 2 + 0.4);
      world.addBox(wall, 0.18, 0.5, d + 0.9, x - w / 2 - 0.4, y0 + h + 0.42, z);
      world.addBox(wall, 0.18, 0.5, d + 0.9, x + w / 2 + 0.4, y0 + h + 0.42, z);
      if (w > 9) {
        world.addBox('metalDark', 1.8, 1.1, 1.2, x + w * 0.22, y0 + h + 0.7, z - d * 0.16);
        world.addBox('metalDark', 1.2, 0.8, 1.4, x - w * 0.28, y0 + h + 0.55, z + d * 0.18);
      }
    }
  } else {
    world.addBox('concreteDark', 1.8, 0.55, 1.2, x - w * 0.2, y0 + 0.28, z + d * 0.18, 0.4);
    world.addBox('woodDark', 1.4, 0.25, 0.3, x + w * 0.15, y0 + 0.15, z - d * 0.1, -0.7);
  }

  if (!ruined) {
    if (w > 8 && d > 7) {
      makeCrate(world, x - w * 0.26, z + d * 0.18, 0.95, 0.2);
      makeCrate(world, x + w * 0.25, z + d * 0.2, 0.78, -0.3);
    }
    if (w > 10) {
      world.addBox('wood', 2.8, 0.16, 0.85, x, y0 + 1.02, z - d * 0.24);
      world.addBox('woodDark', 0.2, 0.9, 0.75, x - 1.22, y0 + 0.52, z - d * 0.24);
      world.addBox('woodDark', 0.2, 0.9, 0.75, x + 1.22, y0 + 0.52, z - d * 0.24);
      world.addCollider(x, y0 + 0.55, z - d * 0.24, 2.9, 1.1, 0.9);
    }
    world.addBox('metal', 0.55, 0.06, 0.55, x + w * 0.2, y0 + h, z - d * 0.1);
  }

  if (site) {
    const spots = [
      [x - w * 0.22, z - d * 0.2],
      [x + w * 0.2, z + d * 0.22],
      [x, z - d * 0.05],
    ];
    world.addLootSpot(spots[0][0], spots[0][1], site);
    world.addLootSpot(spots[1][0], spots[1][1], site);
    if (w > 8) world.addLootSpot(spots[2][0], spots[2][1], site);
  }

  world.buildings.push({ x, z, w, d, h, y0, site: site?.name });
  return { x, z, w, d, h, y0 };
}

function makeWatchtower(world, x, z) {
  const y0 = world.terrainHeight(x, z);
  const legY = y0 + 3.1;
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    world.addBox('woodDark', 0.26, 6.2, 0.26, x + sx * 1.75, legY, z + sz * 1.75);
    world.addCollider(x + sx * 1.75, legY, z + sz * 1.75, 0.3, 6.2, 0.3);
  }
  for (const cy of [y0 + 1.4, y0 + 3.4]) {
    world.addBox('woodDark', 3.5, 0.14, 0.14, x, cy, z - 1.75);
    world.addBox('woodDark', 3.5, 0.14, 0.14, x, cy, z + 1.75);
    world.addBox('woodDark', 0.14, 0.14, 3.5, x - 1.75, cy, z);
    world.addBox('woodDark', 0.14, 0.14, 3.5, x + 1.75, cy, z);
  }
  world.addBox('wood', 4.2, 0.3, 4.2, x, y0 + 6.3, z);
  world.addCollider(x, y0 + 6.3, z, 4.2, 0.35, 4.2);
  for (const [sx, sz, ww, dd] of [[0, -2.05, 4.2, 0.12], [0, 2.05, 4.2, 0.12], [-2.05, 0, 0.12, 4.2], [2.05, 0, 0.12, 4.2]]) {
    world.addBox('woodDark', ww, 0.9, dd, x + sx, y0 + 6.9, z + sz);
  }
  world.addBox('roofMetal', 4.9, 0.16, 4.9, x, y0 + 8.1, z);
  for (const [sx, sz] of [[-2.2, -2.2], [2.2, -2.2], [-2.2, 2.2], [2.2, 2.2]]) {
    world.addBox('woodDark', 0.15, 1.7, 0.15, x + sx, y0 + 7.2, z + sz);
  }
  world.addLootSpot(x + 1.2, z - 1.1, null);
}

function makeSilo(world, x, z) {
  const y0 = world.terrainHeight(x, z);
  world.addCylinder('metal', 2.9, 2.9, 8.6, 14, x, y0 + 4.3, z);
  world.addCylinder('metalDark', 3.05, 2.95, 0.5, 14, x, y0 + 8.55, z);
  const dome = new THREE.SphereGeometry(2.9, 14, 7, 0, Math.PI * 2, 0, Math.PI / 2);
  const m = new THREE.Matrix4().compose(new THREE.Vector3(x, y0 + 8.7, z), new THREE.Quaternion(), new THREE.Vector3(1, 1, 1));
  world.batch('metal', dome, m);
  world.addCollider(x, y0 + 4.3, z, 5.8, 8.6, 5.8);
  for (let i = 0; i < 8; i++) {
    world.addBox('metalDark', 0.9, 0.08, 0.3, x + 2.95, y0 + 1 + i * 0.9, z + 0.5, 0, 0, 0);
  }
}

function makeRadioTower(world, x, z) {
  const y0 = world.terrainHeight(x, z);
  const height = 27;
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    beam(world, 'metalDark', x + sx * 2.4, y0, z + sz * 2.4, x + sx * 0.55, y0 + height, z + sz * 0.55, 0.18);
  }
  for (let i = 1; i <= 5; i++) {
    const t = i / 6;
    const r = 2.4 + (0.55 - 2.4) * t;
    const y = y0 + height * t;
    beam(world, 'metalDark', x - r, y, z - r, x + r, y, z - r, 0.09);
    beam(world, 'metalDark', x - r, y, z + r, x + r, y, z + r, 0.09);
    beam(world, 'metalDark', x - r, y, z - r, x - r, y, z + r, 0.09);
    beam(world, 'metalDark', x + r, y, z - r, x + r, y, z + r, 0.09);
    beam(world, 'metalDark', x - r, y, z - r, x + r, y, z + r, 0.07);
  }
  world.addCylinder('metalDark', 0.12, 0.16, 6, 6, x, y0 + height + 3, z);
  const beaconMat = new THREE.MeshStandardMaterial({ color: 0xff3b2e, emissive: 0xff2418, emissiveIntensity: 0.5, roughness: 0.4 });
  const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.32, 8, 6), beaconMat);
  beacon.position.set(x, y0 + height + 6.1, z);
  world.dynamicGroup.add(beacon);
  world.beacon = beacon;
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    world.addBox('concrete', 0.65, 0.4, 0.65, x + sx * 2.4, y0 + 0.2, z + sz * 2.4);
    world.addCollider(x + sx * 2.4, y0 + 0.4, z + sz * 2.4, 0.7, 0.8, 0.7);
  }
  world.addLootSpot(x + 3.2, z + 2.5, null);
}

function makeFenceLine(world, x1, z1, x2, z2, gap = false, gapSize = 5) {
  const dx = x2 - x1, dz = z2 - z1;
  const len = Math.hypot(dx, dz);
  if (len < 0.5) return;
  const ux = dx / len, uz = dz / len;
  const horizontal = Math.abs(ux) > Math.abs(uz);
  const segments = gap ? [[0, (len - gapSize) / 2 / len], [(len + gapSize) / 2 / len, 1]] : [[0, 1]];
  for (const [a, b] of segments) {
    if (b - a < 0.04) continue;
    const sx = x1 + dx * a, sz = z1 + dz * a;
    const ex = x1 + dx * b, ez = z1 + dz * b;
    const sl = Math.hypot(ex - sx, ez - sz);
    const mx = (sx + ex) / 2, mz = (sz + ez) / 2;
    const y0 = world.terrainHeight(mx, mz);
    world.addBox('woodDark', horizontal ? sl : 0.12, 0.12, horizontal ? 0.12 : sl, mx, y0 + 0.52, mz);
    world.addBox('woodDark', horizontal ? sl : 0.12, 0.12, horizontal ? 0.12 : sl, mx, y0 + 1.0, mz);
    const posts = Math.max(2, Math.round(sl / 3.1));
    for (let i = 0; i <= posts; i++) {
      const t = i / posts;
      world.addBox('woodDark', 0.18, 1.45, 0.18, sx + (ex - sx) * t, world.terrainHeight(sx + (ex - sx) * t, sz + (ez - sz) * t) + 0.72, sz + (ez - sz) * t);
    }
    world.addCollider(mx, y0 + 0.7, mz, horizontal ? sl : 0.2, 1.35, horizontal ? 0.2 : sl);
  }
}

function makeHayBale(world, x, z, ry = 0) {
  const y0 = world.terrainHeight(x, z);
  world.addCylinder('hay', 1.0, 1.0, 1.8, 10, x, y0 + 1.0, z, Math.PI / 2, ry, 0);
  world.addCollider(x, y0 + 1.0, z, 2.0, 2.0, 1.8);
}

function makeShed(world, x, z, w = 7, d = 5.5, h = 3, site = null, door = 'south', wall = 'wood') {
  return makeBuilding(world, { x, z, w, d, h, door, doorWidth: 1.9, wall, roof: 'flat', roofMat: 'roofMetal', site, trim: 'woodDark' });
}

function makeRuinWall(world, x, z, len, h, ry = 0, mat = 'plasterCool') {
  const y0 = world.terrainHeight(x, z);
  world.addBox(mat, len, h, 0.42, x, y0 + h / 2, z, ry);
  const c = Math.cos(ry), s = Math.sin(ry);
  world.addCollider(x, y0 + h / 2, z, Math.abs(c) > 0.5 ? len : 0.42, h, Math.abs(c) > 0.5 ? 0.42 : len);
  for (let i = 0; i < 3; i++) {
    const lx = -len / 2 + 0.8 + i * (len - 1.6) / 2;
    world.addBox('concreteDark', 0.5, 0.25, 0.75, x + lx * c, y0 + 0.14, z - lx * s);
  }
}

