import * as THREE from 'three';
import { WEAPONS, weaponFor, getFlashTexture } from './weapons.js';

const NAMES = [
  'VIPER', 'ROOK', 'NOMAD', 'SPECTER', 'KESTREL', 'JACKAL', 'ORION', 'MACE',
  'TALON', 'SABLE', 'HAVOC', 'ECHO', 'RAVEN', 'CINDER', 'ATLAS', 'FROST',
  'GHOST', 'LYNX', 'ONYX', 'WRAITH', 'BRICK', 'DRIFT', 'CROW', 'EMBER',
];

const VEST_COLORS = [0x5c654a, 0x6e5a44, 0x455c60, 0x6b4c3d, 0x59614e, 0x4d4f5f, 0x746647, 0x48594a];
const SHIRT_COLORS = [0x394236, 0x4d4332, 0x343f42, 0x4f3c32, 0x3d4437, 0x3a3c47, 0x544b37, 0x3a463b];

const GEO = {
  torso: new THREE.BoxGeometry(0.6, 0.66, 0.33),
  vest: new THREE.BoxGeometry(0.67, 0.5, 0.4),
  head: new THREE.BoxGeometry(0.27, 0.29, 0.27),
  helmet: new THREE.BoxGeometry(0.33, 0.13, 0.33),
  visor: new THREE.BoxGeometry(0.32, 0.045, 0.1),
  leg: new THREE.BoxGeometry(0.19, 0.58, 0.23),
  boot: new THREE.BoxGeometry(0.21, 0.2, 0.32),
  arm: new THREE.BoxGeometry(0.13, 0.54, 0.16),
  hand: new THREE.BoxGeometry(0.12, 0.13, 0.14),
  backpack: new THREE.BoxGeometry(0.4, 0.5, 0.22),
  belt: new THREE.BoxGeometry(0.64, 0.1, 0.36),
  gunBody: new THREE.BoxGeometry(0.11, 0.15, 0.78),
  gunBarrel: new THREE.CylinderGeometry(0.026, 0.026, 0.42, 6),
  gunMag: new THREE.BoxGeometry(0.08, 0.2, 0.11),
};

const skinMat = new THREE.MeshStandardMaterial({ color: 0xa97858, roughness: 0.84 });
const pantsMat = new THREE.MeshStandardMaterial({ color: 0x3d423b, roughness: 0.9 });
const bootMat = new THREE.MeshStandardMaterial({ color: 0x24251f, roughness: 0.88 });
const gunMat = new THREE.MeshStandardMaterial({ color: 0x252b27, roughness: 0.55, metalness: 0.35 });
const flashTexture = getFlashTexture();

const damp = (a, b, l, dt) => b + (a - b) * Math.exp(-l * dt);
const lerpAngle = (a, b, t) => {
  let d = ((b - a + Math.PI) % (Math.PI * 2)) - Math.PI;
  if (d < -Math.PI) d += Math.PI * 2;
  return a + d * t;
};

function mesh(parent, geo, mat, x, y, z) {
  const m = new THREE.Mesh(geo, mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

export class Bot {
  constructor(manager, index, name) {
    this.manager = manager;
    this.world = manager.world;
    this.game = manager.game;
    this.index = index;
    this.name = name;
    this.alive = true;
    this.health = 100;
    this.maxHealth = 100;
    this.radius = 0.39;
    this.height = 1.75;
    this.pos = new THREE.Vector3();
    this.yaw = Math.random() * Math.PI * 2;
    this.group = new THREE.Group();
    this.model = new THREE.Group();
    this.group.add(this.model);
    this.weaponId = ['ar', 'ar', 'ar', 'shotgun', 'sniper'][Math.floor(Math.random() * 5)];
    this.def = weaponFor(this.weaponId);

    this.walkPhase = Math.random() * Math.PI * 2;
    this.moveSpeed = 0;
    this.target = null;
    this.targetKind = null;
    this.lastSeen = null;
    this.aiTimer = Math.random() * 0.6;
    this.fireTimer = 0.8 + Math.random();
    this.aimTimer = 0.4;
    this.los = false;
    this.waypoint = null;
    this.waypointTimer = 0;
    this.stuckTimer = 0;
    this.flashTimer = 0;
    this.deathTimer = 0;
    this.strafe = Math.random() > 0.5 ? 1 : -1;
    this.skill = 0.75 + Math.random() * 0.55;

    this.shirtMat = new THREE.MeshStandardMaterial({
      color: SHIRT_COLORS[index % SHIRT_COLORS.length], roughness: 0.86,
    });
    this.vestMat = new THREE.MeshStandardMaterial({
      color: VEST_COLORS[index % VEST_COLORS.length], roughness: 0.72, metalness: 0.06,
      emissive: 0x000000, emissiveIntensity: 0,
    });
    this.accentMat = new THREE.MeshStandardMaterial({ color: 0xc4553f, roughness: 0.65 });
    this.buildModel();
    this.manager.scene.add(this.group);
    this.group.visible = false;
  }

  buildModel() {
    const model = this.model;
    this.torso = new THREE.Group();
    mesh(this.torso, GEO.torso, this.shirtMat, 0, 1.18, 0);
    mesh(this.torso, GEO.vest, this.vestMat, 0, 1.2, -0.01);
    mesh(this.torso, GEO.belt, pantsMat, 0, 0.86, 0);
    mesh(this.torso, GEO.backpack, gunMat, 0, 1.22, 0.27);
    mesh(this.torso, GEO.helmet, this.accentMat, 0.38, 1.31, 0);
    model.add(this.torso);

    this.head = new THREE.Group();
    mesh(this.head, GEO.head, skinMat, 0, 1.72, 0);
    mesh(this.head, GEO.helmet, this.vestMat, 0, 1.9, 0);
    mesh(this.head, GEO.visor, gunMat, 0, 1.8, 0.13);
    model.add(this.head);

    this.leftLeg = new THREE.Group();
    this.leftLeg.position.set(-0.15, 0.88, 0);
    mesh(this.leftLeg, GEO.leg, pantsMat, 0, -0.27, 0);
    mesh(this.leftLeg, GEO.boot, bootMat, 0, -0.62, -0.03);
    model.add(this.leftLeg);

    this.rightLeg = new THREE.Group();
    this.rightLeg.position.set(0.15, 0.88, 0);
    mesh(this.rightLeg, GEO.leg, pantsMat, 0, -0.27, 0);
    mesh(this.rightLeg, GEO.boot, bootMat, 0, -0.62, -0.03);
    model.add(this.rightLeg);

    this.leftArm = new THREE.Group();
    this.leftArm.position.set(-0.37, 1.4, 0);
    mesh(this.leftArm, GEO.arm, this.shirtMat, 0, -0.24, 0);
    mesh(this.leftArm, GEO.hand, skinMat, 0, -0.53, 0);
    model.add(this.leftArm);

    this.rightArm = new THREE.Group();
    this.rightArm.position.set(0.37, 1.4, 0);
    mesh(this.rightArm, GEO.arm, this.shirtMat, 0, -0.24, 0);
    mesh(this.rightArm, GEO.hand, skinMat, 0, -0.53, 0);
    model.add(this.rightArm);

    this.gun = new THREE.Group();
    mesh(this.gun, GEO.gunBody, gunMat, 0, 1.26, -0.42);
    const barrel = new THREE.Mesh(GEO.gunBarrel, gunMat);
    barrel.position.set(0, 1.29, -0.86);
    barrel.rotation.x = Math.PI / 2;
    this.gun.add(barrel);
    mesh(this.gun, GEO.gunMag, gunMat, 0, 1.13, -0.34);
    this.rightArm.rotation.x = -1.15;
    this.leftArm.rotation.x = -1.32;
    this.leftArm.rotation.z = -0.18;
    this.rightArm.rotation.z = -0.12;
    model.add(this.gun);

    this.flash = new THREE.Sprite(new THREE.SpriteMaterial({
      map: flashTexture, color: 0xffd28a, blending: THREE.AdditiveBlending,
      transparent: true, depthWrite: false, opacity: 0.95,
    }));
    this.flash.position.set(0, 1.3, -1.05);
    this.flash.scale.setScalar(0.7);
    this.flash.visible = false;
    model.add(this.flash);
  }

  spawn(x, z) {
    const y = this.world.terrainHeight(x, z);
    this.pos.set(x, y, z);
    this.group.position.copy(this.pos);
    this.group.rotation.y = this.yaw;
    this.group.visible = true;
    this.alive = true;
    this.health = this.maxHealth;
    this.waypoint = null;
  }

  eye() {
    return new THREE.Vector3(this.pos.x, this.pos.y + 1.5, this.pos.z);
  }

  targetEye(target, kind) {
    const p = kind === 'player' ? target.pos : target.pos;
    const h = kind === 'player' ? 1.45 : 1.45;
    return new THREE.Vector3(p.x, p.y + h, p.z);
  }

  selectTarget() {
    const game = this.game;
    const candidates = [];
    if (game.player && !game.player.dead && game.player.mode === 'playing') {
      const d = this.pos.distanceTo(game.player.pos);
      if (d < 88) candidates.push({ ent: game.player, kind: 'player', dist: d });
    }
    for (const bot of this.manager.bots) {
      if (bot === this || !bot.alive) continue;
      const d = this.pos.distanceTo(bot.pos);
      if (d < 78) candidates.push({ ent: bot, kind: 'bot', dist: d });
    }
    candidates.sort((a, b) => a.dist - b.dist);
    const eye = this.eye();
    for (let i = 0; i < Math.min(4, candidates.length); i++) {
      const c = candidates[i];
      const te = this.targetEye(c.ent, c.kind);
      if (!this.world.lineBlocked(eye, te)) {
        if (this.target !== c.ent) this.aimTimer = 0.35 + Math.random() * 0.55;
        this.target = c.ent;
        this.targetKind = c.kind;
        this.los = true;
        this.lastSeen = c.ent.pos.clone();
        return;
      }
    }
    if (this.target && (this.target.dead || (this.targetKind === 'bot' && !this.target.alive))) {
      this.target = null;
      this.targetKind = null;
    }
    this.los = false;
    if (!this.target) this.targetKind = null;
  }

  update(dt, game) {
    if (!this.alive) {
      this.deathTimer += dt;
      if (this.deathTimer > 0.8) {
        this.model.rotation.x = damp(this.model.rotation.x, -Math.PI / 2, 9, dt);
        this.model.position.y = damp(this.model.position.y, 0.4, 9, dt);
      }
      return;
    }
    if (game.state !== 'playing') {
      this.animate(dt, 0);
      return;
    }

    if (this.flashTimer > 0) {
      this.flashTimer -= dt;
      this.vestMat.emissive.setHex(0x7e1a10);
      this.vestMat.emissiveIntensity = Math.max(0, this.flashTimer * 12);
      if (this.flashTimer <= 0) {
        this.vestMat.emissive.setHex(0x000000);
        this.vestMat.emissiveIntensity = 0;
      }
    }
    if (this.flash.visible) {
      this.flash.visible = false;
    }

    this.aiTimer -= dt;
    if (this.aiTimer <= 0) {
      this.aiTimer = 0.42 + Math.random() * 0.3;
      this.selectTarget();
      if (!this.target || !this.los) this.pickWaypoint(game);
    }

    this.updateMovement(dt, game);
    this.updateCombat(dt, game);
    this.animate(dt, this.moveSpeed);
  }

  pickWaypoint(game) {
    const zone = game.zone;
    if (zone && !zone.contains(this.pos.x, this.pos.z)) {
      const a = Math.random() * Math.PI * 2;
      const r = zone.radius * (0.35 + Math.random() * 0.35);
      this.waypoint = { x: zone.center.x + Math.cos(a) * r, z: zone.center.z + Math.sin(a) * r };
      this.waypointTimer = 7;
      return;
    }
    if (this.lastSeen && Math.random() < 0.55) {
      this.waypoint = { x: this.lastSeen.x + (Math.random() - 0.5) * 12, z: this.lastSeen.z + (Math.random() - 0.5) * 12 };
      this.waypointTimer = 5;
      return;
    }
    if (zone) {
      const a = Math.random() * Math.PI * 2;
      const r = zone.radius * (0.15 + Math.random() * 0.65);
      this.waypoint = { x: zone.center.x + Math.cos(a) * r, z: zone.center.z + Math.sin(a) * r };
    } else {
      const a = Math.random() * Math.PI * 2;
      this.waypoint = { x: this.pos.x + Math.cos(a) * 24, z: this.pos.z + Math.sin(a) * 24 };
    }
    this.waypointTimer = 8;
  }

  updateMovement(dt, game) {
    const zone = game.zone;
    let tx = null, tz = null, speed = 3.1;

    if (zone && !zone.contains(this.pos.x, this.pos.z)) {
      const dx = zone.center.x - this.pos.x;
      const dz = zone.center.z - this.pos.z;
      const d = Math.hypot(dx, dz) || 1;
      tx = zone.center.x + (dx / d) * zone.radius * 0.45;
      tz = zone.center.z + (dz / d) * zone.radius * 0.45;
      speed = 4.2;
    } else if (this.target && this.los) {
      const target = this.target;
      const dx = target.pos.x - this.pos.x;
      const dz = target.pos.z - this.pos.z;
      const d = Math.hypot(dx, dz) || 1;
      const ux = dx / d, uz = dz / d;
      if (d > 33) {
        tx = this.pos.x + ux * 12;
        tz = this.pos.z + uz * 12;
        speed = 3.5;
      } else if (d < 11) {
        tx = this.pos.x - ux * 10;
        tz = this.pos.z - uz * 10;
        speed = 3.4;
      } else {
        tx = this.pos.x - uz * this.strafe * 9 + ux * 1.5;
        tz = this.pos.z + ux * this.strafe * 9 + uz * 1.5;
        speed = 2.5;
        if (Math.random() < 0.006) this.strafe *= -1;
      }
    } else {
      this.waypointTimer -= dt;
      if (!this.waypoint || this.waypointTimer <= 0) this.pickWaypoint(game);
      if (this.waypoint) {
        tx = this.waypoint.x;
        tz = this.waypoint.z;
        speed = 2.7;
      }
    }

    if (tx !== null) {
      let dx = tx - this.pos.x;
      let dz = tz - this.pos.z;
      const d = Math.hypot(dx, dz);
      if (d < 1.4) {
        this.waypoint = null;
      } else {
        dx /= d; dz /= d;
        let sepX = 0, sepZ = 0;
        for (const other of this.manager.bots) {
          if (other === this || !other.alive) continue;
          const ox = this.pos.x - other.pos.x;
          const oz = this.pos.z - other.pos.z;
          const od = ox * ox + oz * oz;
          if (od < 6.25 && od > 0.01) {
            const inv = 1 / Math.sqrt(od);
            sepX += ox * inv;
            sepZ += oz * inv;
          }
        }
        dx = dx * 0.8 + sepX * 0.55;
        dz = dz * 0.8 + sepZ * 0.55;
        const nd = Math.hypot(dx, dz) || 1;
        dx /= nd; dz /= nd;

        const beforeX = this.pos.x, beforeZ = this.pos.z;
        const step = speed * dt;
        this.pos.x += dx * step;
        this.pos.z += dz * step;
        this.world.resolveCircle(this.pos, this.radius, this.height);
        const moved = Math.hypot(this.pos.x - beforeX, this.pos.z - beforeZ);
        if (moved < step * 0.35) {
          this.stuckTimer += dt;
          if (this.stuckTimer > 0.9) {
            this.stuckTimer = 0;
            this.strafe *= -1;
            this.waypoint = null;
            this.pos.x += -dz * 1.2;
            this.pos.z += dx * 1.2;
          }
        } else {
          this.stuckTimer = 0;
        }
        this.moveSpeed = moved / Math.max(dt, 0.001);
      }
      const gy = this.world.terrainHeight(this.pos.x, this.pos.z);
      if (gy < 0.35) {
        this.pos.x *= 0.985;
        this.pos.z *= 0.985;
        this.waypoint = null;
      }
      this.pos.y = damp(this.pos.y, this.world.terrainHeight(this.pos.x, this.pos.z), 18, dt);
    } else {
      this.moveSpeed = damp(this.moveSpeed, 0, 6, dt);
    }

    const face = this.target && this.los
      ? Math.atan2(-(this.target.pos.x - this.pos.x), -(this.target.pos.z - this.pos.z))
      : (this.waypoint ? Math.atan2(-(tx - this.pos.x), -(tz - this.pos.z)) : this.yaw);
    if (Number.isFinite(face)) this.yaw = lerpAngle(this.yaw, face, 1 - Math.exp(-7 * dt));
    this.group.position.copy(this.pos);
    this.group.rotation.y = this.yaw;
  }

  updateCombat(dt, game) {
    if (!this.target || !this.los) return;
    const target = this.target;
    if (target.dead || (this.targetKind === 'bot' && !target.alive)) {
      this.target = null;
      return;
    }
    this.aimTimer -= dt;
    if (this.aimTimer > 0) return;
    this.fireTimer -= dt;
    if (this.fireTimer > 0) return;

    const dist = this.pos.distanceTo(target.pos);
    if (dist > this.def.range) return;

    const origin = this.eye().add(new THREE.Vector3(0, -0.06, 0));
    const targetPos = this.targetEye(target, this.targetKind);
    const miss = (0.22 + dist * 0.0075) / this.skill;
    const perpX = -Math.sin(this.yaw);
    const perpZ = -Math.cos(this.yaw);
    targetPos.x += (Math.random() - 0.5) * miss * 2 * perpX + (Math.random() - 0.5) * miss;
    targetPos.z += (Math.random() - 0.5) * miss * 2 * perpZ + (Math.random() - 0.5) * miss;
    targetPos.y += (Math.random() - 0.5) * miss * 1.4;

    const dir = targetPos.clone().sub(origin);
    const range = this.def.range;
    dir.normalize();
    const hit = game.hitscan(origin, dir, range, this);
    const end = hit ? hit.point : origin.clone().addScaledVector(dir, range);
    game.effects.tracer(origin, end, 0xff9f55, 0.6);
    if (hit) {
      if (hit.bot) {
        hit.bot.damage(Math.min(30, this.def.damage * 0.5), game, this, this.def, false);
      } else if (hit.player) {
        hit.player.damage(Math.min(28, this.def.damage * 0.52), this, game);
      } else {
        game.effects.impact(hit.point, hit.kind);
      }
    }

    this.flash.visible = true;
    this.flash.rotation = Math.random() * Math.PI * 2;
    this.flash.scale.setScalar(0.55 + Math.random() * 0.35);
    this._flashTimeout = 0.05;

    const { dist: d, pan } = game.audio.spatial(origin, game.player.pos, game.player.yaw);
    if (d < 150) game.audio.shot(this.def.sound, d, pan, 0.85);
    this.fireTimer = this.def.id === 'sniper' ? 1.6 + Math.random() * 0.7 : 0.24 + Math.random() * 0.24;
  }

  damage(amount, game, attacker, def, head) {
    if (!this.alive) return;
    this.health -= amount;
    this.flashTimer = 0.14;
    if (this.health <= 0) {
      this.health = 0;
      this.alive = false;
      this.deathTimer = 0;
      this.group.rotation.y = this.yaw;
      this.target = null;
      this.los = false;
      this.flash.visible = false;
      game.onBotKilled(this, attacker, def, head);
    } else {
      if (attacker === game.player) this.aimTimer = Math.max(this.aimTimer, 0.12);
      this.lastAttacker = attacker;
    }
  }

  animate(dt, speed) {
    if (!this.alive) return;
    const target = this.target && this.los;
    if (speed > 0.2) {
      this.walkPhase += dt * (5 + speed * 1.2);
      const swing = Math.min(0.8, 0.28 + speed * 0.08);
      this.leftLeg.rotation.x = Math.sin(this.walkPhase) * swing;
      this.rightLeg.rotation.x = -Math.sin(this.walkPhase) * swing;
      this.leftArm.rotation.x = -1.32 + Math.sin(this.walkPhase) * 0.08;
      this.rightArm.rotation.x = -1.15 + Math.sin(this.walkPhase) * 0.08;
    } else {
      this.walkPhase += dt * 1.2;
      this.leftLeg.rotation.x = damp(this.leftLeg.rotation.x, 0, 8, dt);
      this.rightLeg.rotation.x = damp(this.rightLeg.rotation.x, 0, 8, dt);
      this.leftArm.rotation.x = damp(this.leftArm.rotation.x, -1.32, 8, dt);
      this.rightArm.rotation.x = damp(this.rightArm.rotation.x, -1.15, 8, dt);
    }
    if (target) {
      this.rightArm.rotation.x = -1.35;
      this.leftArm.rotation.x = -1.48;
    }
    if (this.flash.visible) {
      this._flashTimeout -= dt;
      if (this._flashTimeout <= 0) this.flash.visible = false;
    }
  }
}

export class BotManager {
  constructor(scene, world, game) {
    this.scene = scene;
    this.world = world;
    this.game = game;
    this.bots = [];
    this.spawned = false;
  }

  get aliveCount() {
    let n = 0;
    for (const bot of this.bots) if (bot.alive) n++;
    return n;
  }

  isFree(x, z, others) {
    const h = this.world.terrainHeight(x, z);
    if (h < 1.0) return false;
    for (const box of this.world.colliders) {
      if (x > box.minX - 0.7 && x < box.maxX + 0.7 && z > box.minZ - 0.7 && z < box.maxZ + 0.7 && h + 1.6 > box.minY && h < box.maxY) return false;
    }
    for (const o of others) {
      if (Math.hypot(x - o.x, z - o.z) < 4.2) return false;
    }
    return true;
  }

  spawnAll(playerDropCenter = { x: -28, z: -14 }) {
    if (this.spawned) return;
    this.spawned = true;
    const used = [];
    const spawnPoints = [];

    for (let i = 0; i < 8; i++) {
      for (let attempt = 0; attempt < 24; attempt++) {
        const a = Math.random() * Math.PI * 2;
        const r = 28 + Math.random() * 68;
        const x = playerDropCenter.x + Math.cos(a) * r;
        const z = playerDropCenter.z + Math.sin(a) * r;
        if (this.isFree(x, z, used)) {
          spawnPoints.push({ x, z });
          used.push({ x, z });
          break;
        }
      }
    }

    const fallback = this.world.botSpawns.slice().sort(() => Math.random() - 0.5);
    for (const s of fallback) {
      if (spawnPoints.length >= NAMES.length) break;
      if (this.isFree(s.x, s.z, used)) {
        spawnPoints.push({ x: s.x, z: s.z });
        used.push({ x: s.x, z: s.z });
      }
    }
    let guard = 0;
    while (spawnPoints.length < NAMES.length && guard < 200) {
      guard++;
      const a = Math.random() * Math.PI * 2;
      const r = 24 + Math.random() * 170;
      const x = Math.cos(a) * r;
      const z = Math.sin(a) * r;
      if (this.isFree(x, z, used)) {
        spawnPoints.push({ x, z });
        used.push({ x, z });
      }
    }

    const names = NAMES.slice().sort(() => Math.random() - 0.5);
    for (let i = 0; i < Math.min(NAMES.length, spawnPoints.length); i++) {
      const bot = new Bot(this, i, names[i]);
      bot.spawn(spawnPoints[i].x, spawnPoints[i].z);
      this.bots.push(bot);
    }
  }

  update(dt) {
    for (const bot of this.bots) bot.update(dt, this.game);
  }
}

import * as THREE from 'three';

const PARTICLE_GEO = new THREE.SphereGeometry(0.055, 4, 3);
const MATS = {
  dust: new THREE.MeshBasicMaterial({ color: 0xc2ac83 }),
  blood: new THREE.MeshBasicMaterial({ color: 0x9f2721 }),
  spark: new THREE.MeshBasicMaterial({ color: 0xffc45f, blending: THREE.AdditiveBlending, transparent: true }),
};

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.tracers = [];
    this.particles = [];
    this.tracerPool = [];
    for (let i = 0; i < 30; i++) {
      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute('position', new THREE.Float32BufferAttribute([0, 0, 0, 0, 0, 0], 3));
      const material = new THREE.LineBasicMaterial({
        color: 0xffc76a, transparent: true, opacity: 0, depthWrite: false,
        blending: THREE.AdditiveBlending,
      });
      const line = new THREE.Line(geometry, material);
      line.frustumCulled = false;
      line.visible = false;
      scene.add(line);
      this.tracerPool.push({ line, material, life: 0, maxLife: 0.1 });
    }
    for (let i = 0; i < 110; i++) {
      const mesh = new THREE.Mesh(PARTICLE_GEO, MATS.dust);
      mesh.visible = false;
      scene.add(mesh);
      this.particles.push({
        mesh, life: 0, maxLife: 0.4, vel: new THREE.Vector3(), scale: 1, gravity: -6,
      });
    }
  }

  tracer(start, end, color = 0xffc76a, strength = 0.8) {
    let slot = this.tracerPool.find(t => t.life <= 0);
    if (!slot) slot = this.tracerPool[0];
    const p = slot.line.geometry.attributes.position;
    p.setXYZ(0, start.x, start.y, start.z);
    p.setXYZ(1, end.x, end.y, end.z);
    p.needsUpdate = true;
    slot.material.color.setHex(color);
    slot.material.opacity = 0.85 * strength;
    slot.life = 0.075;
    slot.maxLife = 0.075;
    slot.line.visible = true;
    return slot;
  }

  particle(position, mat, speed, life, scale, gravity = -6) {
    let slot = this.particles.find(p => p.life <= 0);
    if (!slot) return;
    slot.mesh.material = mat;
    slot.mesh.visible = true;
    slot.mesh.position.copy(position);
    slot.mesh.scale.setScalar(scale);
    slot.life = life;
    slot.maxLife = life;
    slot.scale = scale;
    slot.gravity = gravity;
    slot.vel.set(
      (Math.random() - 0.5) * speed,
      Math.random() * speed * 0.8 + speed * 0.15,
      (Math.random() - 0.5) * speed,
    );
  }

  impact(point, kind = 'static') {
    const sparkCount = kind === 'terrain' ? 2 : 4;
    for (let i = 0; i < sparkCount; i++) {
      this.particle(point, MATS.spark, 4.5, 0.2 + Math.random() * 0.2, 0.7 + Math.random() * 0.6, -9);
    }
    for (let i = 0; i < 2; i++) {
      this.particle(point, MATS.dust, 1.6, 0.35, 1.4 + Math.random(), -1.5);
    }
  }

  blood(point, head = false) {
    const count = head ? 7 : 4;
    for (let i = 0; i < count; i++) {
      this.particle(point, MATS.blood, 3.2, 0.24 + Math.random() * 0.18, (head ? 1.1 : 0.8) + Math.random() * 0.5, -8);
    }
  }

  dust(point) {
    const pos = new THREE.Vector3(point.x, point.y + 0.15, point.z);
    for (let i = 0; i < 12; i++) {
      const angle = Math.random() * Math.PI * 2;
      const p = pos.clone().add(new THREE.Vector3(Math.cos(angle) * 0.4, 0, Math.sin(angle) * 0.4));
      this.particle(p, MATS.dust, 2.4, 0.55 + Math.random() * 0.4, 1.3 + Math.random() * 1.4, -1.2);
    }
  }

  update(dt) {
    for (const t of this.tracerPool) {
      if (t.life > 0) {
        t.life -= dt;
        t.material.opacity = Math.max(0, (t.life / t.maxLife) * 0.85);
        if (t.life <= 0) t.line.visible = false;
      }
    }
    for (const p of this.particles) {
      if (p.life <= 0) continue;
      p.life -= dt;
      if (p.life <= 0) {
        p.mesh.visible = false;
        continue;
      }
      p.vel.y += p.gravity * dt;
      p.mesh.position.addScaledVector(p.vel, dt);
      p.mesh.scale.setScalar(p.scale * Math.max(0.05, p.life / p.maxLife));
      const ground = p.mesh.position.y;
      if (ground < -2) p.life = 0;
    }
  }
}

import * as THREE from 'three';

const PHASES = [
  { wait: 32, shrink: 30, radius: 155, damage: 2 },
  { wait: 26, shrink: 24, radius: 98, damage: 4 },
  { wait: 22, shrink: 20, radius: 60, damage: 7 },
  { wait: 18, shrink: 18, radius: 32, damage: 11 },
  { wait: 15, shrink: 14, radius: 12, damage: 16 },
  { wait: 10, shrink: 10, radius: 2, damage: 25 },
];

const smooth = t => t * t * (3 - 2 * t);

export class Zone {
  constructor(scene, world, game) {
    this.scene = scene;
    this.world = world;
    this.game = game;
    this.active = false;
    this.phase = 0;
    this.state = 'idle';
    this.center = { x: 0, z: 0 };
    this.radius = 235;
    this.nextCenter = { x: 0, z: 0 };
    this.nextRadius = 155;
    this.timer = 0;
    this.duration = 1;
    this.damage = 0;
    this.damageTick = 0;
    this.startCenter = { x: 0, z: 0 };
    this.startRadius = 235;
    this.finished = false;

    const geo = new THREE.CylinderGeometry(1, 1, 1, 72, 1, true);
    const mat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
      uniforms: { uTime: { value: 0 }, uColor: { value: new THREE.Color('#59c4f0') } },
      vertexShader: `
        varying vec3 vLocal;
        varying vec3 vWorld;
        void main() {
          vLocal = position;
          vec4 wp = modelMatrix * vec4(position, 1.0);
          vWorld = wp.xyz;
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColor;
        varying vec3 vLocal;
        varying vec3 vWorld;
        void main() {
          float h = clamp(vLocal.y + 0.5, 0.0, 1.0);
          float base = pow(1.0 - h, 1.35) * 0.36 + 0.035;
          float scan = 0.72 + 0.28 * sin(vWorld.y * 0.52 - uTime * 5.0);
          float bands = 0.85 + 0.15 * sin(vWorld.y * 2.0 + uTime * 1.2);
          gl_FragColor = vec4(uColor, base * scan * bands);
        }
      `,
    });
    this.wall = new THREE.Mesh(geo, mat);
    this.wall.visible = false;
    this.wall.renderOrder = 3;
    scene.add(this.wall);
    this.material = mat;

    const ringGeo = new THREE.RingGeometry(0.994, 1, 160);
    ringGeo.rotateX(-Math.PI / 2);
    const ringMat = new THREE.MeshBasicMaterial({
      color: 0xe9e2d0, transparent: true, opacity: 0.26, side: THREE.DoubleSide, depthWrite: false,
    });
    this.nextRing = new THREE.Mesh(ringGeo, ringMat);
    this.nextRing.visible = false;
    this.nextRing.renderOrder = 2;
    scene.add(this.nextRing);
  }

  start() {
    this.active = true;
    this.state = 'wait';
    this.phase = 0;
    this.center = { x: 0, z: 0 };
    this.radius = 235;
    this.damage = 0;
    this.damageTick = 0;
    this.finished = false;
    this.pickNext();
    this.timer = PHASES[0].wait;
    this.duration = PHASES[0].wait;
    this.wall.visible = true;
    this.nextRing.visible = true;
    this.updateVisual();
    this.game.ui?.zoneUpdate(this);
  }

  pickNext() {
    const phase = PHASES[Math.min(this.phase, PHASES.length - 1)];
    this.nextRadius = phase.radius;
    const maxOffset = Math.max(0, this.radius - this.nextRadius * 1.08);
    const a = Math.random() * Math.PI * 2;
    const r = Math.sqrt(Math.random()) * maxOffset * 0.82;
    let cx = this.center.x + Math.cos(a) * r;
    let cz = this.center.z + Math.sin(a) * r;
    const limit = 186;
    const d = Math.hypot(cx, cz);
    if (d > limit) { cx *= limit / d; cz *= limit / d; }
    this.nextCenter = { x: cx, z: cz };
  }

  contains(x, z) {
    const dx = x - this.center.x;
    const dz = z - this.center.z;
    return dx * dx + dz * dz <= this.radius * this.radius;
  }

  timeLeft() {
    return Math.max(0, this.timer);
  }

  update(dt) {
    if (!this.active) return;
    this.material.uniforms.uTime.value += dt;
    this.timer -= dt;

    if (this.state === 'wait') {
      if (this.timer <= 0) {
        this.state = 'shrink';
        this.timer = PHASES[Math.min(this.phase, PHASES.length - 1)].shrink;
        this.duration = this.timer;
        this.startCenter = { ...this.center };
        this.startRadius = this.radius;
        this.damage = PHASES[Math.min(this.phase, PHASES.length - 1)].damage;
        this.game.ui?.zonePhase('ZONE CLOSING', `PHASE ${String(this.phase + 1).padStart(2, '0')} · ${Math.round(this.nextRadius)}M RADIUS`);
        this.game.audio.zonePhase();
      }
    } else if (this.state === 'shrink') {
      const t = Math.min(1, 1 - this.timer / this.duration);
      const e = smooth(t);
      this.center.x = this.startCenter.x + (this.nextCenter.x - this.startCenter.x) * e;
      this.center.z = this.startCenter.z + (this.nextCenter.z - this.startCenter.z) * e;
      this.radius = this.startRadius + (this.nextRadius - this.startRadius) * e;
      if (this.timer <= 0) {
        this.center = { ...this.nextCenter };
        this.radius = this.nextRadius;
        this.phase++;
        if (this.phase >= PHASES.length) {
          this.state = 'final';
          this.timer = 0;
          this.damage = 30;
          this.radius = 0;
          this.game.ui?.zonePhase('FINAL CIRCLE', 'NO SAFE GROUND REMAINS');
          this.game.audio.zoneWarn();
        } else {
          this.state = 'wait';
          this.timer = PHASES[this.phase].wait;
          this.duration = this.timer;
          this.pickNext();
          this.game.ui?.zonePhase('NEXT CIRCLE REVEALED', `SHRINKS IN ${Math.ceil(this.timer)}S`);
          this.game.audio.zonePhase();
        }
      }
    }

    this.updateVisual();
    this.applyDamage(dt);
  }

  updateVisual() {
    const height = 150;
    this.wall.position.set(this.center.x, height * 0.5 - 6, this.center.z);
    this.wall.scale.set(Math.max(0.01, this.radius), height, Math.max(0.01, this.radius));
    this.nextRing.position.set(this.nextCenter.x, 0.4, this.nextCenter.z);
    this.nextRing.scale.setScalar(Math.max(0.01, this.nextRadius));
    this.nextRing.visible = this.state !== 'final';
  }

  applyDamage(dt) {
    if (this.damage <= 0) { this.game.ui?.setOutside(false, 0); return; }
    const player = this.game.player;
    const outside = player.mode === 'playing' && !player.dead && !this.contains(player.pos.x, player.pos.z);
    this.game.ui?.setOutside(outside, this.damage);
    if (player.mode !== 'playing' || player.dead) return;

    this.damageTick += dt;
    if (this.damageTick >= 1) {
      this.damageTick -= 1;
      if (outside) player.damage(this.damage, null, this.game, true);
      for (const bot of this.game.botManager.bots) {
        if (!bot.alive) continue;
        if (!this.contains(bot.pos.x, bot.pos.z)) {
          bot.damage(this.damage, this.game, null, null, false);
        }
      }
    }
  }
}

import * as THREE from 'three';

const DIRS = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
const TONES = { gold: 'gold', red: 'red', blue: 'blue' };

export class UI {
  constructor(game) {
    this.game = game;
    this.$ = id => document.getElementById(id);
    this.root = this.$('hud');
    this.menu = this.$('menu');
    this.pause = this.$('pause');
    this.result = this.$('result');
    this.mapScreen = this.$('map-screen');
    this.minimap = this.$('minimap');
    this.mapCtx = this.minimap.getContext('2d');
    this.bigMap = this.$('big-map');
    this.bigCtx = this.bigMap.getContext('2d');
    this.compass = this.$('compass');
    this.compassCtx = this.compass.getContext('2d');
    this.crosshair = this.$('crosshair');
    this.damageVignette = this.$('damage-vignette');
    this.zoneVignette = this.$('zone-vignette');
    this.healVignette = this.$('heal-vignette');
    this.hitmarkerEl = this.$('hitmarker');
    this.killfeedEl = this.$('killfeed');
    this.toastStack = this.$('toast-stack');
    this.phaseBanner = this.$('phase-banner');
    this.phaseKicker = this.$('phase-kicker');
    this.phaseTitle = this.$('phase-title');
    this.healthFill = this.$('health-fill');
    this.armorFill = this.$('armor-fill');
    this.healthValue = this.$('health-value');
    this.armorValue = this.$('armor-value');
    this.healthState = this.$('health-state');
    this.medCount = this.$('med-count');
    this.killCount = this.$('kill-count');
    this.magAmmo = this.$('mag-ammo');
    this.reserveAmmo = this.$('reserve-ammo');
    this.weaponName = this.$('weapon-name');
    this.weaponType = this.$('weapon-type');
    this.fireMode = this.$('fire-mode');
    this.weaponSlots = this.$('weapon-slots');
    this.reloadFill = this.$('reload-fill');
    this.reloadTrack = document.querySelector('.reload-track');
    this.zoneClock = this.$('zone-clock');
    this.zoneLabel = this.$('zone-label');
    this.aliveCount = this.$('alive-count');
    this.locationName = this.$('location-name');
    this.coordReadout = this.$('coord-readout');
    this.buildBar = this.$('build-bar');
    this.woodCount = this.$('wood-count');
    this.buildValid = this.$('build-valid');
    this.dropReadout = this.$('drop-readout');
    this.altitude = this.$('altitude');
    this.dropHint = this.$('drop-hint');
    this.controlHint = this.$('control-hint');
    this.interactPrompt = this.$('interact-prompt');
    this.touchFire = this.$('touch-fire');
    this.minimapWrap = this.$('minimap-wrap');
    this.vitalsPanel = document.querySelector('.vitals-panel');
    this.scope = this.$('scope-overlay');

    this.lastCompass = -1;
    this.lastMapDraw = 0;
    this.lastBigDraw = 0;
    this.lastWeaponSignature = '';
    this.weaponSlotEls = [];
    this.zoneOutside = false;
    this.hintTimer = 12;
    this.bannerTimer = 0;
    this.mapOpen = false;
    this.lastLocation = '';
    this.lastCoord = '';
    this.toastTimers = new Set();

    this.bind();
  }

  bind() {
    this.minimapWrap.addEventListener('click', () => {
      if (this.game.state === 'playing' || this.game.state === 'paused') this.openMap();
    });
    this.$('map-close').addEventListener('click', () => this.closeMap());
    this.$('map-screen').addEventListener('click', e => {
      if (e.target === this.mapScreen) this.closeMap();
    });
    document.querySelectorAll('.build-piece').forEach(btn => {
      btn.addEventListener('click', () => {
        this.game.player.setBuildType(btn.dataset.piece, this.game);
      });
    });
    this.$('sound-toggle').addEventListener('click', () => {
      const muted = this.game.audio.toggle();
      const b = this.$('sound-toggle').querySelector('b');
      b.textContent = muted ? 'OFF' : 'ON';
      this.$('sound-toggle').classList.toggle('off', muted);
    });
  }

  bootDone() {
    const boot = this.$('boot');
    boot.classList.add('done');
    setTimeout(() => boot.classList.add('hidden'), 900);
  }

  showMenu() {
    this.menu.classList.remove('hidden', 'leaving');
    this.root.classList.add('hidden');
    this.result.classList.add('hidden');
    this.pause.classList.add('hidden');
  }

  startGame() {
    this.menu.classList.add('leaving');
    setTimeout(() => this.menu.classList.add('hidden'), 550);
    this.root.classList.remove('hidden');
    this.result.classList.add('hidden');
    this.pause.classList.add('hidden');
    this.hintTimer = 13;
    this.controlHint.classList.remove('fade');
    this.weaponSlots.innerHTML = '';
    this.lastWeaponSignature = '';
    if (window.matchMedia('(pointer: coarse)').matches || window.innerWidth < 760) {
      document.body.classList.add('touch');
    }
  }

  showPause() {
    this.pause.classList.remove('hidden');
  }

  hidePause() {
    this.pause.classList.add('hidden');
  }

  toast(title, detail = '', tone = '') {
    const el = document.createElement('div');
    el.className = `toast ${TONES[tone] || ''}`;
    el.innerHTML = `<strong></strong><span></span>`;
    el.querySelector('strong').textContent = title;
    el.querySelector('span').textContent = detail;
    this.toastStack.appendChild(el);
    while (this.toastStack.children.length > 3) {
      this.toastStack.firstElementChild.remove();
    }
    const timer = setTimeout(() => {
      el.classList.add('out');
      setTimeout(() => el.remove(), 380);
      this.toastTimers.delete(timer);
    }, 2700);
    this.toastTimers.add(timer);
  }

  zonePhase(title, subtitle) {
    this.phaseKicker.textContent = subtitle;
    this.phaseTitle.textContent = title;
    this.phaseBanner.classList.add('visible');
    clearTimeout(this._bannerTimer);
    this._bannerTimer = setTimeout(() => this.phaseBanner.classList.remove('visible'), 3600);
  }

  killfeed(entry) {
    const el = document.createElement('div');
    el.className = 'kill-entry';
    const killer = document.createElement('b');
    killer.textContent = entry.killer || 'ZONE';
    if (entry.killer === 'YOU') killer.classList.add('you');
    const arrow = document.createElement('i');
    arrow.textContent = '▸';
    const victim = document.createElement('b');
    victim.textContent = entry.victim;
    const weapon = document.createElement('em');
    weapon.textContent = entry.weapon || 'ZONE';
    el.append(killer, arrow, victim, weapon);
    this.killfeedEl.appendChild(el);
    while (this.killfeedEl.children.length > 5) this.killfeedEl.firstElementChild.remove();
    setTimeout(() => {
      el.classList.add('out');
      setTimeout(() => el.remove(), 420);
    }, 6000);
  }

  hitmarker(head = false, killed = false) {
    const el = this.hitmarkerEl;
    el.classList.remove('show', 'head', 'kill');
    void el.offsetWidth;
    el.classList.add('show');
    if (head) el.classList.add('head');
    if (killed) el.classList.add('kill');
  }

  damage(amount, attacker) {
    this.damageVignette.classList.add('hit');
    clearTimeout(this._damageTimer);
    this._damageTimer = setTimeout(() => this.damageVignette.classList.remove('hit'), 170);
    if (amount > 12) this.game.player.shake = Math.max(this.game.player.shake, 0.12);
  }

  setOutside(active, dps) {
    this.zoneOutside = active;
    this.zoneVignette.classList.toggle('active', active);
    if (active) {
      this.zoneLabel.textContent = 'OUTSIDE';
      this.zoneLabel.style.color = 'var(--red)';
    }
  }

  setBuildMode(active, type = 'wall', materials = 0) {
    this.buildBar.classList.toggle('hidden', !active);
    document.body.classList.toggle('building', active);
    this.touchFire.textContent = active ? 'PLACE' : 'FIRE';
    this.touchFire.classList.toggle('placing', active);
    if (active) {
      document.querySelectorAll('.build-piece').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.piece === type);
      });
      this.woodCount.textContent = materials;
      this.weaponName.textContent = 'BUILD MODE';
      this.weaponType.textContent = 'STRUCTURES';
    }
  }

  updateBuildValid(valid, materials) {
    this.woodCount.textContent = materials;
    this.buildBar.style.borderTopColor = valid ? 'var(--gold)' : 'var(--red)';
  }

  update(game) {
    const player = game.player;
    const world = game.world;
    const zone = game.zone;

    if (player.mode === 'drop') {
      this.dropReadout.classList.remove('hidden');
      this.altitude.textContent = Math.max(0, Math.round(player.pos.y - world.terrainHeight(player.pos.x, player.pos.z)));
      this.dropHint.textContent = player.chuteOpen ? 'STEER WITH WASD · LAND NEAR LOOT' : 'STEER WITH WASD · CHUTE AUTO-DEPLOYS AT 55M';
    } else {
      this.dropReadout.classList.add('hidden');
    }

    const def = player.activeDef;
    const ammo = player.ammoText();
    this.magAmmo.textContent = ammo.mag;
    this.reserveAmmo.textContent = ammo.reserve;
    if (!player.buildMode) {
      this.weaponName.textContent = def ? def.name : 'UNARMED';
      this.weaponType.textContent = def ? def.typeLabel : 'NO WEAPON';
      this.fireMode.textContent = def ? def.mode : '—';
    }
    this.healthFill.style.width = `${Math.max(0, player.health)}%`;
    this.armorFill.style.width = `${Math.max(0, player.armor)}%`;
    this.healthValue.textContent = Math.ceil(player.health);
    this.armorValue.textContent = Math.ceil(player.armor);
    this.medCount.textContent = player.meds;
    this.killCount.textContent = player.kills;
    this.vitalsPanel.classList.toggle('low', player.health <= 30);
    this.healthState.textContent = player.health <= 0 ? 'DOWN' : player.health < 30 ? 'CRITICAL' : player.health < 65 ? 'WOUNDED' : 'STABLE';
    this.woodCount.textContent = player.materials;

    if (this.reloadTrack) {
      const reloading = player.reloadTimer > 0;
      this.reloadTrack.classList.toggle('active', reloading);
      if (reloading) this.reloadFill.style.width = `${(1 - player.reloadTimer / player.reloadTotal) * 100}%`;
    }

    const sig = player.weapons.map(w => w ? `${w.id}:${w.mag}:${w.reserve}` : 'empty').join('|');
    if (sig !== this.lastWeaponSignature || this.weaponSlotEls.length === 0) {
      this.updateWeaponSlots(player);
      this.lastWeaponSignature = sig;
    } else {
      this.weaponSlotEls.forEach((el, i) => el.classList.toggle('active', i === player.currentSlot));
    }

    this.crosshair.style.setProperty('--spread', `${Math.round(7 + player.shotSpread * 380 + Math.min(8, player.moveSpeed * 0.8))}px`);
    this.crosshair.classList.toggle('aiming', player.aiming);
    this.crosshair.style.opacity = player.buildMode || player.mode === 'drop' || player.dead ? '0' : '1';

    this.aliveCount.textContent = 1 + game.botManager.aliveCount;
    this.zoneClock.textContent = this.formatTime(zone.timeLeft());
    if (zone.state === 'shrink') {
      this.zoneLabel.textContent = 'CLOSING';
      this.zoneLabel.style.color = 'var(--red)';
    } else if (zone.state === 'final') {
      this.zoneLabel.textContent = 'FINAL';
      this.zoneLabel.style.color = 'var(--red)';
    } else if (!this.zoneOutside) {
      this.zoneLabel.textContent = 'NEXT ZONE';
      this.zoneLabel.style.color = 'var(--blue)';
    }
    document.querySelector('.zone-readout').classList.toggle('danger', zone.state === 'shrink' || zone.state === 'final' || this.zoneOutside);
    this.zoneClock.style.color = zone.state === 'shrink' || this.zoneOutside ? 'var(--red)' : '';

    const { site, distance } = world.nearestSite(player.pos.x, player.pos.z);
    const location = distance < site.r * 1.25 ? site.name : distance < 80 ? 'OUTSKIRTS' : 'ISLA VERDE';
    if (location !== this.lastLocation) {
      this.locationName.textContent = location;
      this.lastLocation = location;
    }
    const coord = `X ${String(Math.round(player.pos.x)).padStart(3, '0')} · Z ${String(Math.round(player.pos.z)).padStart(3, '0')}`;
    if (coord !== this.lastCoord) {
      this.coordReadout.textContent = coord;
      this.lastCoord = coord;
    }

    if (Math.abs(player.yaw - this.lastCompass) > 0.003) {
      this.drawCompass(player);
      this.lastCompass = player.yaw;
    }
    const now = performance.now();
    if (now - this.lastMapDraw > 90) {
      this.drawMinimap(game);
      this.lastMapDraw = now;
    }
    if (this.mapOpen && now - this.lastBigDraw > 90) {
      this.drawBigMap(game);
      this.lastBigDraw = now;
    }

    this.controlHint.classList.toggle('fade', game.elapsed > 13);
    if (this.zoneOutside) {
      this.healthState.textContent = 'IN THE BLUE';
    }
  }

  updateWeaponSlots(player) {
    this.weaponSlots.innerHTML = '';
    this.weaponSlotEls = [];
    player.weapons.forEach((w, i) => {
      const el = document.createElement('div');
      el.className = `wslot${i === player.currentSlot ? ' active' : ''}`;
      const b = document.createElement('b');
      b.textContent = i + 1;
      const span = document.createElement('span');
      if (w) {
        const wd = w.id === 'ar' ? 'RANGER' : w.id === 'shotgun' ? 'BREACH' : w.id === 'sniper' ? 'M40' : 'P9';
        span.textContent = wd;
      } else {
        span.textContent = 'EMPTY';
      }
      el.append(b, span);
      this.weaponSlots.appendChild(el);
      this.weaponSlotEls.push(el);
    });
  }

  drawCompass(player) {
    const ctx = this.compassCtx;
    const w = this.compass.width;
    const h = this.compass.height;
    const heading = ((-player.yaw * 180 / Math.PI) % 360 + 360) % 360;
    const span = 120;
    const pxPerDeg = w / span;
    ctx.clearRect(0, 0, w, h);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (let d = Math.floor(heading - span / 2); d <= heading + span / 2; d++) {
      const norm = ((d % 360) + 360) % 360;
      const x = w / 2 + (d - heading) * pxPerDeg;
      if (x < 0 || x > w) continue;
      const major = norm % 45 === 0;
      const mid = norm % 15 === 0;
      const alpha = 0.2 + 0.7 * (1 - Math.abs(d - heading) / (span / 2));
      ctx.strokeStyle = major ? `rgba(242,193,78,${alpha})` : `rgba(241,234,217,${alpha * 0.55})`;
      ctx.lineWidth = major ? 1.4 : 1;
      ctx.beginPath();
      ctx.moveTo(x, h - (major ? 16 : mid ? 9 : 5));
      ctx.lineTo(x, h - 1);
      ctx.stroke();
      if (major) {
        ctx.fillStyle = `rgba(241,234,217,${alpha})`;
        ctx.font = '500 15px "IBM Plex Mono", monospace';
        ctx.fillText(DIRS[(norm / 45) % 8], x, 12);
        if (norm % 90 === 45) {
          ctx.font = '500 10px "IBM Plex Mono", monospace';
          ctx.fillStyle = `rgba(165,169,157,${alpha})`;
          ctx.fillText(String(norm).padStart(3, '0'), x, 27);
        }
      } else if (mid) {
        ctx.fillStyle = `rgba(165,169,157,${alpha * 0.6})`;
        ctx.font = '400 8px "IBM Plex Mono", monospace';
        ctx.fillText(String(norm), x, 26);
      }
    }
    ctx.fillStyle = 'rgba(242,193,78,0.9)';
    ctx.font = '500 11px "IBM Plex Mono", monospace';
    ctx.fillText(String(Math.round(heading)).padStart(3, '0') + '°', w / 2, 39);
  }

  drawZone(ctx, game, size) {
    const zone = game.zone;
    if (!zone || !zone.active) return;
    const scale = size / 560;
    const [cx, cy] = game.world.worldToMap(zone.center.x, zone.center.z, size);
    const r = zone.radius * scale;

    ctx.save();
    ctx.beginPath();
    ctx.rect(0, 0, size, size);
    if (r > 0.5) ctx.arc(cx, cy, r, 0, Math.PI * 2, true);
    ctx.fillStyle = 'rgba(52, 163, 218, 0.26)';
    ctx.fill('evenodd');
    ctx.restore();

    ctx.save();
    ctx.strokeStyle = 'rgba(96, 188, 232, 0.9)';
    ctx.lineWidth = Math.max(1.5, size / 340);
    ctx.beginPath();
    ctx.arc(cx, cy, Math.max(0.5, r), 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();

    if (zone.state !== 'final' && zone.nextRadius > 0.5) {
      const [nx, ny] = game.world.worldToMap(zone.nextCenter.x, zone.nextCenter.z, size);
      ctx.save();
      ctx.setLineDash([size / 90, size / 90]);
      ctx.strokeStyle = 'rgba(241, 234, 217, 0.8)';
      ctx.lineWidth = Math.max(1, size / 500);
      ctx.beginPath();
      ctx.arc(nx, ny, zone.nextRadius * scale, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
  }

  drawPlayerArrow(ctx, game, size, scale = 1) {
    const player = game.player;
    if (player.dead) return;
    const [px, py] = game.world.worldToMap(player.pos.x, player.pos.z, size);
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(-player.yaw);
    ctx.beginPath();
    ctx.moveTo(0, -10 * scale);
    ctx.lineTo(7 * scale, 8 * scale);
    ctx.lineTo(0, 4 * scale);
    ctx.lineTo(-7 * scale, 8 * scale);
    ctx.closePath();
    ctx.fillStyle = '#f2c14e';
    ctx.shadowColor = 'rgba(242,193,78,.8)';
    ctx.shadowBlur = 7 * scale;
    ctx.fill();
    ctx.strokeStyle = 'rgba(12,17,14,0.9)';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.restore();
  }

  drawMinimap(game) {
    const ctx = this.mapCtx;
    const size = this.minimap.width;
    const world = game.world;
    ctx.clearRect(0, 0, size, size);
    if (world.mapCanvas) ctx.drawImage(world.mapCanvas, 0, 0, size, size);
    this.drawZone(ctx, game, size);

    const player = game.player;
    const [px, py] = world.worldToMap(player.pos.x, player.pos.z, size);
    const scale = size / 560;
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(-player.yaw);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.arc(0, 0, 74 * scale, -Math.PI / 2 - 0.38, -Math.PI / 2 + 0.38);
    ctx.closePath();
    ctx.fillStyle = 'rgba(242,193,78,0.09)';
    ctx.fill();
    ctx.restore();

    for (const bot of game.botManager.bots) {
      if (!bot.alive) continue;
      const d = Math.hypot(bot.pos.x - player.pos.x, bot.pos.z - player.pos.z);
      if (d > 72) continue;
      const [bx, by] = world.worldToMap(bot.pos.x, bot.pos.z, size);
      ctx.beginPath();
      ctx.arc(bx, by, Math.max(2.2, size / 180), 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(239,79,69,0.95)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(20,8,6,0.75)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
    this.drawPlayerArrow(ctx, game, size, 1.15);
  }

  drawBigMap(game) {
    const ctx = this.bigCtx;
    const size = this.bigMap.width;
    const world = game.world;
    ctx.clearRect(0, 0, size, size);
    if (world.mapCanvas) ctx.drawImage(world.mapCanvas, 0, 0, size, size);
    this.drawZone(ctx, game, size);
    this.drawPlayerArrow(ctx, game, size, 1.6);
    const zone = game.zone;
    this.$('map-zone-label').textContent = zone.state === 'final'
      ? 'FINAL CIRCLE'
      : zone.state === 'shrink'
        ? `ZONE CLOSING · ${Math.ceil(zone.timeLeft())}S`
        : `NEXT SHRINK · ${Math.ceil(zone.timeLeft())}S`;
  }

  formatTime(seconds) {
    const s = Math.max(0, Math.ceil(seconds));
    return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
  }

  openMap() {
    this.mapOpen = true;
    this.mapScreen.classList.remove('hidden');
    this.drawBigMap(this.game);
  }

  closeMap() {
    this.mapOpen = false;
    this.mapScreen.classList.add('hidden');
  }

  toggleMap() {
    if (this.mapOpen) this.closeMap();
    else if (this.game.state === 'playing' || this.game.state === 'paused') this.openMap();
  }

  showResult(win, stats) {
    this.result.classList.remove('hidden');
    this.result.classList.toggle('win', win);
    this.$('result-kicker').textContent = win ? 'MATCH VICTORY' : 'MATCH COMPLETE';
    this.$('result-title').textContent = win ? 'WINNER' : 'ELIMINATED';
    this.$('result-subtitle').textContent = win
      ? 'Last operator standing. The island is yours.'
      : stats.killedBy ? `Taken down by ${stats.killedBy}. The circle moves on.` : 'The island claims another operator.';
    this.$('stat-placement').textContent = `#${stats.placement}`;
    this.$('stat-kills').textContent = stats.kills;
    this.$('stat-damage').textContent = stats.damage;
    this.$('stat-time').textContent = this.formatTime(stats.time);
    if (win) this.confetti();
  }

  confetti() {
    const old = this.result.querySelector('.confetti');
    if (old) old.remove();
    const layer = document.createElement('div');
    layer.className = 'confetti';
    const colors = ['#f2c14e', '#e46b42', '#60bce8', '#f1ead9', '#83d783'];
    for (let i = 0; i < 46; i++) {
      const piece = document.createElement('i');
      piece.style.left = `${Math.random() * 100}%`;
      piece.style.background = colors[Math.floor(Math.random() * colors.length)];
      piece.style.animationDuration = `${2.4 + Math.random() * 2.2}s`;
      piece.style.animationDelay = `${Math.random() * 0.8}s`;
      piece.style.transform = `rotate(${Math.random() * 180}deg)`;
      layer.appendChild(piece);
    }
    this.result.querySelector('.result-inner').appendChild(layer);
  }

  refreshMap() {
    this.lastMapDraw = 0;
    this.lastBigDraw = 0;
  }
}

