229:   update(game) {
230:     const player = game.player;
231:     const world = game.world;
232:     const zone = game.zone;
233: 
234:     if (player.mode === 'drop') {
235:       this.dropReadout.classList.remove('hidden');
236:       this.altitude.textContent = Math.max(0, Math.round(player.pos.y - world.terrainHeight(player.pos.x, player.pos.z)));
237:       this.dropHint.textContent = player.chuteOpen ? 'STEER WITH WASD · LAND NEAR LOOT' : 'STEER WITH WASD · CHUTE AUTO-DEPLOYS AT 55M';
238:     } else {
239:       this.dropReadout.classList.add('hidden');
240:     }
241: 
242:     const def = player.activeDef;
243:     const ammo = player.ammoText();
244:     this.magAmmo.textContent = ammo.mag;
245:     this.reserveAmmo.textContent = ammo.reserve;
246:     if (!player.buildMode) {
247:       this.weaponName.textContent = def ? def.name : 'UNARMED';
248:       this.weaponType.textContent = def ? def.typeLabel : 'NO WEAPON';
249:       this.fireMode.textContent = def ? def.mode : '—';
250:     }
251:     this.healthFill.style.width = `${Math.max(0, player.health)}%`;
252:     this.armorFill.style.width = `${Math.max(0, player.armor)}%`;
253:     this.healthValue.textContent = Math.ceil(player.health);
254:     this.armorValue.textContent = Math.ceil(player.armor);
255:     this.medCount.textContent = player.meds;
256:     this.killCount.textContent = player.kills;
257:     this.vitalsPanel.classList.toggle('low', player.health <= 30);
258:     this.healthState.textContent = player.health <= 0 ? 'DOWN' : player.health < 30 ? 'CRITICAL' : player.health < 65 ? 'WOUNDED' : 'STABLE';
259:     this.woodCount.textContent = player.materials;
260: 
261:     if (this.reloadTrack) {
262:       const reloading = player.reloadTimer > 0;
263:       this.reloadTrack.classList.toggle('active', reloading);
264:       if (reloading) this.reloadFill.style.width = `${(1 - player.reloadTimer / player.reloadTotal) * 100}%`;
265:     }
266: 
267:     const sig = player.weapons.map(w => w ? `${w.id}:${w.mag}:${w.reserve}` : 'empty').join('|');
268:     if (sig !== this.lastWeaponSignature || this.weaponSlotEls.length === 0) {
269:       this.updateWeaponSlots(player);
270:       this.lastWeaponSignature = sig;
271:     } else {
272:       this.weaponSlotEls.forEach((el, i) => el.classList.toggle('active', i === player.currentSlot));
273:     }
274: 
275:     this.crosshair.style.setProperty('--spread', `${Math.round(7 + player.shotSpread * 380 + Math.min(8, player.moveSpeed * 0.8))}px`);
276:     this.crosshair.classList.toggle('aiming', player.aiming);
277:     this.crosshair.style.opacity = player.buildMode || player.mode === 'drop' || player.dead ? '0' : '1';
278: 
279:     this.aliveCount.textContent = 1 + game.botManager.aliveCount;
280:     this.zoneClock.textContent = this.formatTime(zone.timeLeft());
281:     if (zone.state === 'shrink') {
282:       this.zoneLabel.textContent = 'CLOSING';
283:       this.zoneLabel.style.color = 'var(--red)';
284:     } else if (zone.state === 'final') {
285:       this.zoneLabel.textContent = 'FINAL';
286:       this.zoneLabel.style.color = 'var(--red)';
287:     } else if (!this.zoneOutside) {
288:       this.zoneLabel.textContent = 'NEXT ZONE';
289:       this.zoneLabel.style.color = 'var(--blue)';
290:     }
291:     document.querySelector('.zone-readout').classList.toggle('danger', zone.state === 'shrink' || zone.state === 'final' || this.zoneOutside);
292:     this.zoneClock.style.color = zone.state === 'shrink' || this.zoneOutside ? 'var(--red)' : '';
293: 
294:     const { site, distance } = world.nearestSite(player.pos.x, player.pos.z);
295:     const location = distance < site.r * 1.25 ? site.name : distance < 80 ? 'OUTSKIRTS' : 'ISLA VERDE';
296:     if (location !== this.lastLocation) {
297:       this.locationName.textContent = location;
298:       this.lastLocation = location;
299:     }
300:     const coord = `X ${String(Math.round(player.pos.x)).padStart(3, '0')} · Z ${String(Math.round(player.pos.z)).padStart(3, '0')}`;
301:     if (coord !== this.lastCoord) {
302:       this.coordReadout.textContent = coord;
303:       this.lastCoord = coord;
304:     }
305: 
306:     if (Math.abs(player.yaw - this.lastCompass) > 0.003) {
307:       this.drawCompass(player);
308:       this.lastCompass = player.yaw;
309:     }
310:     const now = performance.now();
311:     if (now - this.lastMapDraw > 90) {
312:       this.drawMinimap(game);
313:       this.lastMapDraw = now;
314:     }
315:     if (this.mapOpen && now - this.lastBigDraw > 90) {
316:       this.drawBigMap(game);
317:       this.lastBigDraw = now;
318:     }
319: 
320:     this.controlHint.classList.toggle('fade', game.elapsed > 13);
321:     if (this.zoneOutside) {
322:       this.healthState.textContent = 'IN THE BLUE';
323:     }
324:   }
