347:   drawCompass(player) {
348:     const ctx = this.compassCtx;
349:     const w = this.compass.width;
350:     const h = this.compass.height;
351:     const heading = ((-player.yaw * 180 / Math.PI) % 360 + 360) % 360;
352:     const span = 120;
353:     const pxPerDeg = w / span;
354:     ctx.clearRect(0, 0, w, h);
355:     ctx.textAlign = 'center';
356:     ctx.textBaseline = 'middle';
357:     for (let d = Math.floor(heading - span / 2); d <= heading + span / 2; d++) {
358:       const norm = ((d % 360) + 360) % 360;
359:       const x = w / 2 + (d - heading) * pxPerDeg;
360:       if (x < 0 || x > w) continue;
361:       const major = norm % 45 === 0;
362:       const mid = norm % 15 === 0;
363:       const alpha = 0.2 + 0.7 * (1 - Math.abs(d - heading) / (span / 2));
364:       ctx.strokeStyle = major ? `rgba(242,193,78,${alpha})` : `rgba(241,234,217,${alpha * 0.55})`;
365:       ctx.lineWidth = major ? 1.4 : 1;
366:       ctx.beginPath();
367:       ctx.moveTo(x, h - (major ? 16 : mid ? 9 : 5));
368:       ctx.lineTo(x, h - 1);
369:       ctx.stroke();
370:       if (major) {
371:         ctx.fillStyle = `rgba(241,234,217,${alpha})`;
372:         ctx.font = '500 15px "IBM Plex Mono", monospace';
373:         ctx.fillText(DIRS[(norm / 45) % 8], x, 12);
374:         if (norm % 90 === 45) {
375:           ctx.font = '500 10px "IBM Plex Mono", monospace';
376:           ctx.fillStyle = `rgba(165,169,157,${alpha})`;
377:           ctx.fillText(String(norm).padStart(3, '0'), x, 27);
378:         }
379:       } else if (mid) {
380:         ctx.fillStyle = `rgba(165,169,157,${alpha * 0.6})`;
381:         ctx.font = '400 8px "IBM Plex Mono", monospace';
382:         ctx.fillText(String(norm), x, 26);
383:       }
384:     }
385:     ctx.fillStyle = 'rgba(242,193,78,0.9)';
386:     ctx.font = '500 11px "IBM Plex Mono", monospace';
387:     ctx.fillText(String(Math.round(heading)).padStart(3, '0') + '°', w / 2, 39);
388:   }
