390:   drawZone(ctx, game, size) {
391:     const zone = game.zone;
392:     if (!zone || !zone.active) return;
393:     const scale = size / 560;
394:     const [cx, cy] = game.world.worldToMap(zone.center.x, zone.center.z, size);
395:     const r = zone.radius * scale;
396: 
397:     ctx.save();
398:     ctx.beginPath();
399:     ctx.rect(0, 0, size, size);
400:     if (r > 0.5) ctx.arc(cx, cy, r, 0, Math.PI * 2, true);
401:     ctx.fillStyle = 'rgba(52, 163, 218, 0.26)';
402:     ctx.fill('evenodd');
403:     ctx.restore();
404: 
405:     ctx.save();
406:     ctx.strokeStyle = 'rgba(96, 188, 232, 0.9)';
407:     ctx.lineWidth = Math.max(1.5, size / 340);
408:     ctx.beginPath();
409:     ctx.arc(cx, cy, Math.max(0.5, r), 0, Math.PI * 2);
410:     ctx.stroke();
411:     ctx.restore();
412: 
413:     if (zone.state !== 'final' && zone.nextRadius > 0.5) {
414:       const [nx, ny] = game.world.worldToMap(zone.nextCenter.x, zone.nextCenter.z, size);
415:       ctx.save();
416:       ctx.setLineDash([size / 90, size / 90]);
417:       ctx.strokeStyle = 'rgba(241, 234, 217, 0.8)';
418:       ctx.lineWidth = Math.max(1, size / 500);
419:       ctx.beginPath();
420:       ctx.arc(nx, ny, zone.nextRadius * scale, 0, Math.PI * 2);
421:       ctx.stroke();
422:       ctx.restore();
423:     }
424:   }
