426:   drawPlayerArrow(ctx, game, size, scale = 1) {
427:     const player = game.player;
428:     if (player.dead) return;
429:     const [px, py] = game.world.worldToMap(player.pos.x, player.pos.z, size);
430:     ctx.save();
431:     ctx.translate(px, py);
432:     ctx.rotate(-player.yaw);
433:     ctx.beginPath();
434:     ctx.moveTo(0, -10 * scale);
435:     ctx.lineTo(7 * scale, 8 * scale);
436:     ctx.lineTo(0, 4 * scale);
437:     ctx.lineTo(-7 * scale, 8 * scale);
438:     ctx.closePath();
439:     ctx.fillStyle = '#f2c14e';
440:     ctx.shadowColor = 'rgba(242,193,78,.8)';
441:     ctx.shadowBlur = 7 * scale;
442:     ctx.fill();
443:     ctx.strokeStyle = 'rgba(12,17,14,0.9)';
444:     ctx.lineWidth = 1;
445:     ctx.stroke();
446:     ctx.restore();
447:   }
