449:   drawMinimap(game) {
450:     const ctx = this.mapCtx;
451:     const size = this.minimap.width;
452:     const world = game.world;
453:     ctx.clearRect(0, 0, size, size);
454:     if (world.mapCanvas) ctx.drawImage(world.mapCanvas, 0, 0, size, size);
455:     this.drawZone(ctx, game, size);
456: 
457:     const player = game.player;
458:     const [px, py] = world.worldToMap(player.pos.x, player.pos.z, size);
459:     const scale = size / 560;
460:     ctx.save();
461:     ctx.translate(px, py);
462:     ctx.rotate(-player.yaw);
463:     ctx.beginPath();
464:     ctx.moveTo(0, 0);
465:     ctx.arc(0, 0, 74 * scale, -Math.PI / 2 - 0.38, -Math.PI / 2 + 0.38);
466:     ctx.closePath();
467:     ctx.fillStyle = 'rgba(242,193,78,0.09)';
468:     ctx.fill();
469:     ctx.restore();
470: 
471:     for (const bot of game.botManager.bots) {
472:       if (!bot.alive) continue;
473:       const d = Math.hypot(bot.pos.x - player.pos.x, bot.pos.z - player.pos.z);
474:       if (d > 72) continue;
475:       const [bx, by] = world.worldToMap(bot.pos.x, bot.pos.z, size);
476:       ctx.beginPath();
477:       ctx.arc(bx, by, Math.max(2.2, size / 180), 0, Math.PI * 2);
478:       ctx.fillStyle = 'rgba(239,79,69,0.95)';
479:       ctx.fill();
480:       ctx.strokeStyle = 'rgba(20,8,6,0.75)';
481:       ctx.lineWidth = 1;
482:       ctx.stroke();
483:     }
484:     this.drawPlayerArrow(ctx, game, size, 1.15);
485:   }
