487:   drawBigMap(game) {
488:     const ctx = this.bigCtx;
489:     const size = this.bigMap.width;
490:     const world = game.world;
491:     ctx.clearRect(0, 0, size, size);
492:     if (world.mapCanvas) ctx.drawImage(world.mapCanvas, 0, 0, size, size);
493:     this.drawZone(ctx, game, size);
494:     this.drawPlayerArrow(ctx, game, size, 1.6);
495:     const zone = game.zone;
496:     this.$('map-zone-label').textContent = zone.state === 'final'
497:       ? 'FINAL CIRCLE'
498:       : zone.state === 'shrink'
499:         ? `ZONE CLOSING · ${Math.ceil(zone.timeLeft())}S`
500:         : `NEXT SHRINK · ${Math.ceil(zone.timeLeft())}S`;
501:   }
