343:   createTerrain() {
344:     const segments = 184;
345:     const geo = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE, segments, segments);
346:     geo.rotateX(-Math.PI / 2);
347:     const pos = geo.attributes.position;
348:     const colors = new Float32Array(pos.count * 3);
349:     const p = this.palette;
350:     const color = new THREE.Color();
351:     const rockColor = new THREE.Color();
352: 
353:     for (let i = 0; i < pos.count; i++) {
354:       const x = pos.getX(i);
355:       const z = pos.getZ(i);
356:       const h = this.terrainHeight(x, z);
357:       pos.setY(i, h);
358: 
359:       const hx = this.terrainHeight(x + 1.7, z);
360:       const hz = this.terrainHeight(x, z + 1.7);
361:       const slope = (Math.abs(h - hx) + Math.abs(h - hz)) / 1.7;
362:       const n = Math.sin(x * 0.73 + z * 1.11) * 0.5 + 0.5;
363:       const n2 = Math.sin(x * 0.17 - z * 0.23) * 0.5 + 0.5;
364: 
365:       color.copy(p.grassA).lerp(p.grassB, n * 0.7 + n2 * 0.3);
366:       if (n2 > 0.67) color.lerp(p.grassC, 0.35);
367:       if (n < 0.32 && h > 1.8) color.lerp(p.dry, 0.25);
368: 
369:       if (h < -0.4) color.copy(p.underwater);
370:       else if (h < 0.9) color.copy(p.wetSand).lerp(p.sand, (h + 0.4) / 1.3);
371:       else if (h < 1.8) color.copy(p.sand).lerp(p.dry, 0.3);
372: 
373:       if (h > 1.5 && slope > 0.92) {
374:         rockColor.copy(p.rock).lerp(p.rockDark, Math.min(1, (slope - 0.9) * 0.7));
375:         color.lerp(rockColor, Math.min(0.86, (slope - 0.9) * 0.95));
376:       }
377: 
378:       let roadDist = 99;
379:       for (const s of this.roadSegments) {
380:         const d = distToSegment(x, z, s.ax, s.az, s.bx, s.bz);
381:         if (d < roadDist) roadDist = d;
382:       }
383:       if (roadDist < 7.2) {
384:         const w = 1 - smoothstep(3.7, 7.2, roadDist);
385:         color.lerp(p.road, w * 0.55);
386:       }
387: 
388:       for (const site of this.sites) {
389:         const d = Math.hypot(x - site.x, z - site.z);
390:         if (d < site.r * 0.82) {
391:           const w = 1 - smoothstep(site.r * 0.35, site.r * 0.82, d);
392:           color.lerp(p.dirt, w * 0.28);
393:         }
394:       }
395: 
396:       colors[i * 3] = color.r;
397:       colors[i * 3 + 1] = color.g;
398:       colors[i * 3 + 2] = color.b;
399:     }
400: 
401:     geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
402:     geo.computeVertexNormals();
403:     const mat = new THREE.MeshStandardMaterial({
404:       vertexColors: true, roughness: 0.97, metalness: 0.0, flatShading: true,
405:     });
406:     const mesh = new THREE.Mesh(geo, mat);
407:     mesh.receiveShadow = true;
408:     mesh.name = 'terrain';
409:     this.terrain = mesh;
410:     this.root.add(mesh);
411:   }
