560:   raycastStatic(origin, dir, maxDist) {
561:     let best = null;
562:     for (const box of this.colliders) {
563:       const t = rayAabb(origin, dir, box, maxDist);
564:       if (t !== null && t >= 0 && t < maxDist && (!best || t < best.distance)) {
565:         best = { distance: t, box };
566:       }
567:     }
568:     if (best) {
569:       best.point = {
570:         x: origin.x + dir.x * best.distance,
571:         y: origin.y + dir.y * best.distance,
572:         z: origin.z + dir.z * best.distance,
573:       };
574:       return best;
575:     }
576:     return null;
577:   }
