579:   raycast(origin, dir, maxDist = 300) {
580:     const staticHit = this.raycastStatic(origin, dir, maxDist);
581:     let best = staticHit || null;
582:     let terrainHit = null;
583:     const step = 2.2;
584:     for (let t = 0.5; t < maxDist; t += step) {
585:       const x = origin.x + dir.x * t;
586:       const y = origin.y + dir.y * t;
587:       const z = origin.z + dir.z * t;
588:       const h = this.terrainHeight(x, z);
589:       if (y <= h) {
590:         terrainHit = {
591:           distance: t,
592:           point: { x, y: h, z },
593:           kind: 'terrain',
594:         };
595:         break;
596:       }
597:     }
598:     if (terrainHit && (!best || terrainHit.distance < best.distance)) best = terrainHit;
599:     return best;
600:   }
