602:   lineBlocked(a, b) {
603:     const dx = b.x - a.x, dy = b.y - a.y, dz = b.z - a.z;
604:     const len = Math.hypot(dx, dy, dz);
605:     if (len < 0.01) return false;
606:     const dir = { x: dx / len, y: dy / len, z: dz / len };
607:     const hit = this.raycastStatic(a, dir, len * 0.96);
608:     if (hit) return true;
609:     const steps = Math.max(3, Math.ceil(len / 9));
610:     for (let i = 1; i < steps; i++) {
611:       const t = (i / steps) * len;
612:       const y = a.y + dy * (i / steps);
613:       if (y < this.terrainHeight(a.x + dx * (i / steps), a.z + dz * (i / steps)) + 0.12) return true;
614:     }
615:     return false;
616:   }
