618:   resolveCircle(pos, radius, height = 1.8) {
619:     const feet = pos.y;
620:     const head = pos.y + height;
621:     for (let iteration = 0; iteration < 2; iteration++) {
622:       for (const box of this.colliders) {
623:         if (head < box.minY + 0.08 || feet > box.maxY - 0.08) continue;
624:         const cx = Math.max(box.minX, Math.min(pos.x, box.maxX));
625:         const cz = Math.max(box.minZ, Math.min(pos.z, box.maxZ));
626:         let dx = pos.x - cx;
627:         let dz = pos.z - cz;
628:         const d2 = dx * dx + dz * dz;
629:         if (d2 > radius * radius) continue;
630:         if (d2 > 0.000001) {
631:           const d = Math.sqrt(d2);
632:           const push = radius - d;
633:           pos.x += (dx / d) * push;
634:           pos.z += (dz / d) * push;
635:         } else {
636:           const toLeft = pos.x - box.minX;
637:           const toRight = box.maxX - pos.x;
638:           const toBack = pos.z - box.minZ;
639:           const toFront = box.maxZ - pos.z;
640:           const min = Math.min(toLeft, toRight, toBack, toFront);
641:           if (min === toLeft) pos.x = box.minX - radius;
642:           else if (min === toRight) pos.x = box.maxX + radius;
643:           else if (min === toBack) pos.z = box.minZ - radius;
644:           else pos.z = box.maxZ + radius;
645:         }
646:       }
647:     }
648:     const d = Math.hypot(pos.x, pos.z);
649:     if (d > ISLAND_RADIUS - 2) {
650:       const s = (ISLAND_RADIUS - 2) / d;
651:       pos.x *= s;
652:       pos.z *= s;
653:     }
654:     return pos;
655:   }
