  font-family: 'Barlow Condensed';
  src: url('../fonts/barlow-condensed-800.woff2') format('woff2');
  font-weight: 800;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'IBM Plex Mono';
  src: url('../fonts/ibm-plex-mono-400.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'IBM Plex Mono';
  src: url('../fonts/ibm-plex-mono-500.woff2') format('woff2');
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'IBM Plex Mono';
  src: url('../fonts/ibm-plex-mono-600.woff2') format('woff2');
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}

:root {
  --ink: #080b0a;
  --ink-2: #0d1211;
  --panel: rgba(12, 17, 16, 0.74);
  --panel-solid: #111715;
  --cream: #f1ead9;
  --muted: #a5a99d;
  --dim: #72786e;
  --gold: #f2c14e;
  --gold-hot: #ffd66e;
  --orange: #e46b42;
  --red: #ef4f45;
  --blue: #60bce8;
  --green: #83d783;
  --line: rgba(241, 234, 217, 0.16);
  --line-soft: rgba(241, 234, 217, 0.08);
  --mono: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  --display: 'Barlow Condensed', 'Arial Narrow', Impact, sans-serif;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--cream);
  font-family: var(--display);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  position: fixed;
  inset: 0;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

button, input { font: inherit; }
button { color: inherit; }

.hidden { display: none !important; }

#stage { position: absolute; inset: 0; overflow: hidden; background: #9ab6c3; }
#game { display: block; width: 100%; height: 100%; outline: none; }

.stage-vignette {
  position: absolute; inset: 0; pointer-events: none;
  background:
    radial-gradient(130% 100% at 50% 38%, transparent 42%, rgba(3, 6, 5, 0.38) 100%),
    linear-gradient(180deg, rgba(5, 8, 7, 0.12), transparent 22%, transparent 74%, rgba(3, 6, 5, 0.45));
}

.stage-grain {
  position: absolute; inset: 0; pointer-events: none; opacity: 0.055; mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.88' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='160' height='160' filter='url(%23n)' opacity='0.65'/%3E%3C/svg%3E");
  background-size: 170px 170px;
}

#damage-vignette, #zone-vignette, #heal-vignette, #scope-overlay {
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
}

#damage-vignette {
  background: radial-gradient(circle at 50% 50%, transparent 28%, rgba(181, 27, 22, 0.7) 112%);
  transition: opacity 0.22s ease-out;
  z-index: 2;
}
#damage-vignette.hit { opacity: 1; transition: opacity 0.04s; }
#zone-vignette {
  background:
    radial-gradient(circle at 50% 50%, transparent 36%, rgba(37, 128, 173, 0.34) 100%),
    linear-gradient(180deg, rgba(64, 166, 209, 0.12), rgba(18, 66, 91, 0.2));
  z-index: 2;
  transition: opacity 0.4s;
}
#zone-vignette.active { opacity: 1; animation: zonePulse 2.2s ease-in-out infinite; }
#heal-vignette {
  background: radial-gradient(circle at 50% 60%, rgba(116, 209, 132, 0.12), transparent 60%);
  transition: opacity 0.5s;
  z-index: 2;
}
#heal-vignette.active { opacity: 1; }

#scope-overlay {
  z-index: 3;
  transition: opacity 0.16s;
  background: radial-gradient(circle at 50% 50%, transparent 0 29vh, rgba(0, 0, 0, 0.92) calc(29vh + 2px), #000 calc(29vh + 3px));
}
#scope-overlay.active { opacity: 1; }
#scope-overlay::before, #scope-overlay::after {
  content: ''; position: absolute; left: 50%; top: 50%; background: rgba(10, 15, 13, 0.8);
}
#scope-overlay::before { width: 1px; height: 58vh; transform: translate(-50%, -50%); }
#scope-overlay::after { height: 1px; width: 58vh; transform: translate(-50%, -50%); }

@keyframes zonePulse { 0%, 100% { opacity: 0.65; } 50% { opacity: 1; } }

/* ---------------- shared screen layers ---------------- */

.screen { position: absolute; inset: 0; z-index: 20; }

.eyebrow {
  display: inline-flex; align-items: center; gap: 10px;
  margin: 0; font-family: var(--mono); font-size: 10px; font-weight: 500;
  letter-spacing: 0.24em; text-transform: uppercase; color: var(--gold);
}
.eyebrow > span { width: 28px; height: 1px; background: var(--gold); display: inline-block; }

kbd {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 27px; height: 23px; padding: 0 6px;
  border: 1px solid rgba(241, 234, 217, 0.26);
  background: rgba(241, 234, 217, 0.06);
  border-radius: 2px; font-family: var(--mono); font-size: 9px;
  color: var(--cream); letter-spacing: 0.06em;
}

/* ---------------- boot ---------------- */

.deploy-copy { display: flex; flex-direction: column; gap: 1px; }
.deploy-copy strong { font-size: 32px; line-height: 1; font-weight: 800; letter-spacing: 0.06em; }
.deploy-copy small { font-family: var(--mono); font-size: 8px; font-weight: 500; letter-spacing: 0.19em; }
.deploy-arrow { margin-left: auto; font-size: 24px; font-weight: 600; }
.match-facts { display: flex; flex-direction: column; gap: 6px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.17em; color: var(--muted); }
.match-facts span { display: flex; align-items: center; gap: 8px; }
.match-facts span::before { content: ''; width: 3px; height: 3px; background: var(--gold); border-radius: 50%; }

.feature-row {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); width: min(680px, 100%);
  margin-top: 38px; border-top: 1px solid var(--line); padding-top: 17px; gap: 15px;
  animation: rise 0.9s 0.52s both;
}
.feature-row div { display: flex; flex-direction: column; gap: 3px; }
.feature-row b { font-family: var(--mono); font-size: 8px; font-weight: 500; color: var(--gold); letter-spacing: 0.14em; }
.feature-row span { font-size: 20px; line-height: 1; font-weight: 700; letter-spacing: 0.1em; }
.feature-row small { font-family: var(--mono); font-size: 7px; letter-spacing: 0.08em; color: var(--dim); text-transform: uppercase; }

.briefing {
  position: relative; align-self: center; width: 100%; max-width: 430px; justify-self: end;
  padding: 24px 26px 20px; margin-bottom: 2vh;
  background: linear-gradient(155deg, rgba(15, 21, 19, 0.88), rgba(9, 13, 11, 0.76));
  border: 1px solid rgba(241, 234, 217, 0.14); border-top: 2px solid var(--gold);
  backdrop-filter: blur(14px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%);
  animation: slideIn 0.9s 0.5s both;
}
.briefing::before {
  content: ''; position: absolute; inset: 0; opacity: 0.5; pointer-events: none;
  background: repeating-linear-gradient(180deg, transparent 0 4px, rgba(255, 255, 255, 0.018) 4px 5px);
}
.briefing-head { display: flex; justify-content: space-between; align-items: baseline; border-bottom: 1px solid var(--line); padding-bottom: 13px; margin-bottom: 4px; }
.briefing-head span { font-size: 15px; font-weight: 700; letter-spacing: 0.17em; }
.briefing-head em { font-family: var(--mono); font-style: normal; font-size: 9px; color: var(--gold); letter-spacing: 0.14em; }
.briefing-step { display: flex; gap: 14px; padding: 13px 0; border-bottom: 1px solid var(--line-soft); }
.briefing-step > b { font-family: var(--mono); font-size: 9px; color: var(--gold); padding-top: 2px; font-weight: 500; }
.briefing-step strong { display: block; font-size: 14px; letter-spacing: 0.12em; font-weight: 600; }
.briefing-step p { margin: 4px 0 0; font-family: var(--mono); font-size: 8px; line-height: 1.7; letter-spacing: 0.02em; color: var(--muted); }
.controls-table { margin-top: 16px; display: flex; flex-direction: column; gap: 8px; }
.controls-table > div { display: grid; grid-template-columns: 46px 1fr 54px 1fr; align-items: center; gap: 7px; }
.controls-table span { font-family: var(--mono); font-size: 8px; letter-spacing: 0.1em; color: var(--muted); }
.controls-table kbd { min-width: 0; width: 100%; height: 22px; font-size: 8px; }
.briefing-foot {
  display: flex; align-items: center; gap: 8px; margin-top: 18px; padding-top: 13px; border-top: 1px solid var(--line);
  font-family: var(--mono); font-size: 7px; letter-spacing: 0.14em; color: var(--dim);
}
.briefing-foot em { margin-left: auto; font-style: normal; color: var(--muted); }
.signal { width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); }

.menu-footer {
  position: relative; z-index: 2; display: flex; align-items: center; justify-content: space-between;
  padding: 0 calc(38px + var(--safe-r)) calc(20px + var(--safe-b)) calc(38px + var(--safe-l));
  font-family: var(--mono); font-size: 8px; letter-spacing: 0.16em; color: var(--dim);
}
.menu-footer > span { display: flex; align-items: center; gap: 8px; }
.menu-footer i { width: 4px; height: 4px; border-radius: 50%; background: var(--gold); }
.sound-toggle {
  display: flex; align-items: center; gap: 8px; border: 1px solid var(--line); background: rgba(10, 14, 12, 0.5);
  padding: 7px 10px; cursor: pointer; font-family: var(--mono); font-size: 7px; letter-spacing: 0.14em; color: var(--muted);
  transition: border-color 0.2s, color 0.2s;
}
.sound-toggle b { color: var(--green); font-weight: 500; }
.sound-toggle.off b { color: var(--red); }
.sound-toggle:hover { border-color: rgba(242, 193, 78, 0.5); color: var(--cream); }

@keyframes rise { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }
@keyframes slideIn { from { opacity: 0; transform: translateX(26px); } to { opacity: 1; transform: translateX(0); } }

/* ---------------- HUD ---------------- */

#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }

.hud-top {
  position: absolute; top: 0; left: 0; right: 0;
  display: grid; grid-template-columns: minmax(180px, 1fr) minmax(280px, 500px) minmax(180px, 1fr);
  align-items: start; gap: 20px;
  padding: calc(17px + var(--safe-t)) calc(26px + var(--safe-r)) 0 calc(26px + var(--safe-l));
}
.brand { display: flex; align-items: center; gap: 11px; padding-top: 4px; }
.brand-mark {
  position: relative; display: grid; place-items: center; width: 30px; height: 30px;
  border: 1px solid rgba(242, 193, 78, 0.55); transform: rotate(45deg);
}
.brand-mark i { width: 8px; height: 8px; border: 1px solid var(--gold); }
.brand-copy { display: flex; flex-direction: column; gap: 2px; line-height: 1; }
.brand-copy strong { font-size: 17px; letter-spacing: 0.12em; font-weight: 700; }
.brand-copy span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.14em; color: var(--muted); }

.compass-shell {
  position: relative; width: 100%; height: 44px; margin-top: 1px;
  overflow: hidden;
  mask-image: linear-gradient(90deg, transparent, #000 14%, #000 86%, transparent);
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 14%, #000 86%, transparent);
}
#compass { width: 100%; height: 100%; display: block; opacity: 0.94; }
.compass-pip { position: absolute; top: 0; left: 50%; width: 1px; height: 10px; background: var(--gold); transform: translateX(-50%); box-shadow: 0 0 8px rgba(242, 193, 78, 0.8); }
.compass-pip::after { content: ''; position: absolute; top: 10px; left: -3px; width: 5px; height: 5px; background: var(--gold); clip-path: polygon(0 0, 100% 0, 50% 100%); }

.match-stack { display: flex; justify-content: flex-end; align-items: flex-start; gap: 18px; }
.match-count { display: flex; flex-direction: column; align-items: flex-end; gap: 1px; padding-top: 3px; }
.match-count span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.2em; color: var(--muted); }
.match-count strong { font-size: 34px; line-height: 0.95; font-weight: 700; letter-spacing: 0.02em; }
.zone-readout {
  display: flex; flex-direction: column; align-items: flex-end; gap: 2px;
  min-width: 90px; padding: 7px 10px; border-left: 1px solid var(--line);
  background: linear-gradient(90deg, transparent, rgba(7, 11, 9, 0.4));
}
.zone-readout span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.15em; color: var(--blue); }
.zone-readout strong { font-family: var(--mono); font-size: 16px; line-height: 1; font-weight: 500; color: var(--cream); }
.zone-readout.danger span, .zone-readout.danger strong { color: var(--red); animation: dangerBlink 0.8s infinite; }
@keyframes dangerBlink { 50% { opacity: 0.4; } }

.minimap-wrap { position: absolute; top: calc(79px + var(--safe-t)); right: calc(26px + var(--safe-r)); width: 188px; pointer-events: auto; cursor: pointer; }
.minimap-frame {
  position: relative; width: 100%; aspect-ratio: 1; overflow: hidden;
  background: rgba(7, 11, 9, 0.84);
  border: 1px solid rgba(241, 234, 217, 0.28);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
}
.minimap-frame canvas { width: 100%; height: 100%; display: block; }
.minimap-scan {
  position: absolute; inset: 0; pointer-events: none;
  background: repeating-linear-gradient(180deg, transparent 0 3px, rgba(6, 12, 10, 0.19) 3px 4px);
  box-shadow: inset 0 0 40px rgba(0, 0, 0, 0.28);
}
.corner { position: absolute; width: 9px; height: 9px; border-color: var(--gold); border-style: solid; opacity: 0.9; }
.c1 { top: 4px; left: 4px; border-width: 1px 0 0 1px; }
.c2 { top: 4px; right: 4px; border-width: 1px 1px 0 0; }
.c3 { bottom: 4px; left: 4px; border-width: 0 0 1px 1px; }
.c4 { bottom: 4px; right: 4px; border-width: 0 1px 1px 0; }
.minimap-meta {
  display: flex; justify-content: space-between; align-items: center; gap: 6px;
  padding: 7px 9px; background: rgba(8, 12, 10, 0.85);
  border: 1px solid rgba(241, 234, 217, 0.16); border-top: 0;
}
.minimap-meta > span:first-child { font-size: 12px; letter-spacing: 0.14em; font-weight: 600; }
.minimap-meta .coord { font-family: var(--mono); font-size: 6px; letter-spacing: 0.04em; color: var(--dim); }

.killfeed {
  position: absolute; top: calc(79px + 234px + var(--safe-t)); right: calc(26px + var(--safe-r));
  width: 300px; display: flex; flex-direction: column; align-items: flex-end; gap: 5px;
}
.kill-entry {
  display: flex; align-items: center; gap: 7px; max-width: 100%;
  padding: 6px 9px; background: linear-gradient(90deg, rgba(8, 12, 10, 0.55), rgba(8, 12, 10, 0.88));
  border-right: 2px solid rgba(241, 234, 217, 0.3);
  font-family: var(--mono); font-size: 8px; letter-spacing: 0.05em; color: var(--muted);
  animation: feedIn 0.24s ease both;
}
.kill-entry.out { animation: feedOut 0.4s ease both; }
.kill-entry b { color: var(--cream); font-weight: 500; }
.kill-entry b.you { color: var(--gold); }
.kill-entry i { font-style: normal; color: var(--red); font-size: 9px; }
.kill-entry em { font-style: normal; color: var(--dim); font-size: 7px; text-transform: uppercase; }
@keyframes feedIn { from { opacity: 0; transform: translateX(18px); } }
@keyframes feedOut { to { opacity: 0; transform: translateX(18px); } }

.phase-banner {
  position: absolute; top: calc(84px + var(--safe-t)); left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  opacity: 0; transition: opacity 0.4s; text-align: center;
}
.phase-banner.visible { opacity: 1; }
.phase-banner span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.28em; color: var(--blue); }
.phase-banner strong { font-size: 20px; font-weight: 600; letter-spacing: 0.16em; text-shadow: 0 2px 14px rgba(0, 0, 0, 0.6); }

.drop-readout {
  position: absolute; top: 16%; left: 50%; transform: translateX(-50%);
  display: flex; align-items: baseline; gap: 7px; padding: 14px 20px;
  background: linear-gradient(180deg, rgba(8, 12, 10, 0.7), rgba(8, 12, 10, 0.34));
.toast.gold strong { color: var(--gold); }
.toast.red strong { color: var(--red); }
.toast.blue strong { color: var(--blue); }
.toast.out { animation: toastOut 0.35s ease both; }
@keyframes toastIn { from { opacity: 0; transform: translateY(7px); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-5px); } }

.control-hint {
  position: absolute; left: 50%; bottom: 5px; transform: translateX(-50%);
  font-family: var(--mono); font-size: 6px; letter-spacing: 0.08em; color: rgba(241, 234, 217, 0.32);
  white-space: nowrap; transition: opacity 1.2s; pointer-events: none;
}
.control-hint.fade { opacity: 0; }
.control-hint span { color: rgba(242, 193, 78, 0.55); margin-left: 7px; }
.control-hint span:first-child { margin-left: 0; }

/* ---------------- touch controls ---------------- */

.touch-ui { display: none; }
body.touch .touch-ui { display: block; position: absolute; inset: 0; pointer-events: none; }
body.touch .weapon-hint, body.touch .control-hint { display: none; }

.joystick {
  position: absolute; left: calc(20px + var(--safe-l)); bottom: calc(20px + var(--safe-b));
  width: 118px; height: 118px; border-radius: 50%; pointer-events: auto;
  background: radial-gradient(circle, rgba(241, 234, 217, 0.05), rgba(8, 12, 10, 0.15));
  border: 1px solid rgba(241, 234, 217, 0.21);
  touch-action: none;
}
.joystick-ring { position: absolute; inset: 17px; border-radius: 50%; border: 1px dashed rgba(241, 234, 217, 0.16); }
.joystick-knob {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px; border-radius: 50%;
  background: radial-gradient(circle at 38% 34%, rgba(255, 245, 213, 0.35), rgba(242, 193, 78, 0.16));
  border: 1px solid rgba(242, 193, 78, 0.55); box-shadow: 0 0 18px rgba(242, 193, 78, 0.1);
}
.touch-side { position: absolute; right: calc(14px + var(--safe-r)); bottom: calc(18px + var(--safe-b)); width: 218px; height: 190px; pointer-events: none; }
.tbtn {
  position: absolute; pointer-events: auto; display: grid; place-items: center;
  border-radius: 50%; border: 1px solid rgba(241, 234, 217, 0.28);
  background: radial-gradient(circle at 35% 30%, rgba(241, 234, 217, 0.16), rgba(8, 12, 10, 0.42));
  backdrop-filter: blur(5px); color: var(--cream); font-family: var(--mono); font-size: 8px; letter-spacing: 0.08em;
  touch-action: none;
}
.tbtn:active { background: rgba(242, 193, 78, 0.25); }
.tbtn-fire { right: 0; bottom: 0; width: 94px; height: 94px; border-color: rgba(228, 107, 66, 0.55); font-size: 12px; font-weight: 600; color: #ffd7c8; background: radial-gradient(circle at 35% 30%, rgba(228, 107, 66, 0.4), rgba(70, 20, 12, 0.4)); }
.tbtn-jump { right: 104px; bottom: 4px; width: 62px; height: 62px; }
.tbtn-build { right: 4px; bottom: 102px; width: 62px; height: 54px; border-radius: 10px; font-size: 7px; }
.tbtn-reload { right: 76px; bottom: 72px; width: 52px; height: 52px; font-size: 6px; }
.tbtn-heal { right: 134px; bottom: 72px; width: 52px; height: 52px; font-size: 6px; }
.tbtn-swap { right: 170px; bottom: 4px; width: 48px; height: 48px; font-size: 6px; }
.tbtn-small { color: rgba(241, 234, 217, 0.8); }

/* ---------------- pause / result / map ---------------- */

.pause, .result, .map-screen {
  display: flex; align-items: center; justify-content: center;
  background:
    radial-gradient(circle at 50% 40%, rgba(242, 193, 78, 0.05), transparent 45%),
    rgba(4, 7, 6, 0.8); backdrop-filter: blur(9px);
}
.pause-card, .result-inner {
  position: relative; width: min(480px, calc(100vw - 36px)); padding: 38px 40px 32px;
  background: linear-gradient(155deg, rgba(16, 22, 20, 0.96), rgba(8, 12, 10, 0.92));
  border: 1px solid rgba(241, 234, 217, 0.16); border-top: 2px solid var(--gold);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 26px), calc(100% - 26px) 100%, 0 100%);
  text-align: center; animation: cardIn 0.4s cubic-bezier(0.2, 0.9, 0.2, 1) both;
}
@keyframes cardIn { from { opacity: 0; transform: translateY(18px) scale(0.98); } }
.pause-card h2, .result-inner h2 { margin: 8px 0 8px; font-size: 72px; line-height: 0.8; font-weight: 800; letter-spacing: 0.04em; }
.pause-card p, .result-inner > p { margin: 0 auto 24px; max-width: 320px; font-family: var(--mono); font-size: 9px; line-height: 1.7; color: var(--muted); }
.solid-btn {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  width: 100%; height: 62px; border: 0; cursor: pointer; color: #17130b;
  background: linear-gradient(105deg, var(--gold-hot), var(--gold) 60%, #d9a52e);
  clip-path: polygon(0 0, calc(100% - 13px) 0, 100% 13px, 100% 100%, 13px 100%, 0 calc(100% - 13px));
  transition: filter 0.2s, transform 0.2s; margin-bottom: 8px;
}
